{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with AWS Secrets Manager integration",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

'use strict';

/**
 * secrets.js — Unified secret-resolution module
 *
 * Resolution order for every secret:
 *   1. AWS Secrets Manager  (always attempted first in non-development environments)
 *   2. Local .env.test file (fallback when NODE_ENV=development OR when Secrets Manager
 *      is unreachable, so the app still starts on a developer laptop without AWS creds)
 *
 * Secret names are never hard-coded here.  The authoritative list is read at startup
 * from .env.test so that adding a new secret requires only one file change.
 *
 * Usage
 * -----
 *   const { getSecret } = require('./secrets');
 *
 *   // Returns a resolved string value (or throws if the secret cannot be found).
 *   const dbUrl = await getSecret('DATABASE_URL');
 */

const path = require('path');
const fs   = require('fs');

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover required secret names AND supply local values
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parse a .env file and return a plain object of key→value pairs.
 * Handles:
 *  - comment lines (# …)
 *  - blank lines
 *  - optional surrounding quotes on values
 *  - inline comments after the value
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const entries = {};
  const raw = fs.readFileSync(filePath, 'utf8');

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const key = trimmed.slice(0, eqIdx).trim();
    // Everything after the first '=' up to an optional inline comment
    let value = trimmed.slice(eqIdx + 1).trim();
    // Strip surrounding quotes (single or double)
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) entries[key] = value;
  }

  return entries;
}

// Local values parsed from .env.test — used only as a development/fallback source
const localEnv = parseEnvFile(ENV_FILE);

// Derive the authoritative list of required secret names from the keys in .env.test
const REQUIRED_SECRET_NAMES = Object.keys(localEnv);

if (REQUIRED_SECRET_NAMES.length === 0) {
  console.warn('[secrets] Warning: .env.test is empty or missing — no secrets registered.');
} else {
  console.log(`[secrets] Registered ${REQUIRED_SECRET_NAMES.length} secret(s): ${REQUIRED_SECRET_NAMES.join(', ')}`);
}

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client
// ---------------------------------------------------------------------------

// Region falls back to a sensible default so local dev doesn't need AWS_REGION set
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';

const smClient = new SecretsManagerClient({ region: AWS_REGION });

/**
 * Fetch a single secret from AWS Secrets Manager by its name.
 *
 * Secrets Manager can store a value either as a plain string or as a JSON object.
 * When the stored value is JSON the function looks for a top-level key that
 * matches `name`; otherwise the raw string is returned as-is.
 *
 * @param  {string} name  The secret name (must match the name in Secrets Manager).
 * @returns {Promise<string>}
 * @throws  Will re-throw any Secrets Manager error that is NOT a "not found" variant.
 */
async function fetchFromSecretsManager(name) {
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await smClient.send(command);
  const raw = response.SecretString ?? Buffer.from(response.SecretBinary, 'base64').toString('utf8');

  // If the secret is stored as a JSON bundle, extract by key name
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && name in parsed) {
      return String(parsed[name]);
    }
    // JSON object but no matching key — return the whole JSON string so the
    // caller can decide what to do with it (avoids silently swallowing data)
    return raw;
  } catch {
    // Not JSON — plain string secret
    return raw;
  }
}

// ---------------------------------------------------------------------------
// 3. In-process cache to avoid redundant network round-trips
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const cache = new Map();

// ---------------------------------------------------------------------------
// 4. Public API
// ---------------------------------------------------------------------------

const IS_DEVELOPMENT = (process.env.NODE_ENV || 'development') === 'development';

/**
 * Resolve a secret value by name.
 *
 * Resolution order:
 *   - Development (NODE_ENV=development):
 *       .env.test  →  Secrets Manager  →  throw
 *   - All other environments:
 *       Secrets Manager  →  .env.test (fallback if SM unreachable)  →  throw
 *
 * Results are cached in-process for the lifetime of the application.
 *
 * @param  {string} name  The secret name as it appears in .env.test and/or Secrets Manager.
 * @returns {Promise<string>}
 * @throws  {Error}  When the secret cannot be resolved from any source.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    throw new Error(
      `[secrets] "${name}" is not a registered secret. ` +
      `Registered secrets: ${REQUIRED_SECRET_NAMES.join(', ')}`
    );
  }

  // Return cached value if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  let value;

  if (IS_DEVELOPMENT) {
    // ── Development: prefer local file so the app works without AWS credentials ──
    if (name in localEnv) {
      console.log(`[secrets] (dev) Resolved "${name}" from .env.test`);
      value = localEnv[name];
    } else {
      // Local file didn't have it — try Secrets Manager anyway
      console.log(`[secrets] (dev) "${name}" not in .env.test, trying Secrets Manager…`);
      value = await fetchFromSecretsManager(name);
      console.log(`[secrets] (dev) Resolved "${name}" from Secrets Manager`);
    }
  } else {
    // ── Production / staging: Secrets Manager is authoritative ──
    try {
      value = await fetchFromSecretsManager(name);
      console.log(`[secrets] Resolved "${name}" from Secrets Manager`);
    } catch (err) {
      // Allow fallback to local env only for well-known "not found / no access" errors
      const isAccessError = [
        'ResourceNotFoundException',
        'AccessDeniedException',
        'InvalidRequestException',
        'ResourceNotReady',
      ].includes(err.name) || err.code === 'NetworkingError';

      if (isAccessError && name in localEnv) {
        console.warn(
          `[secrets] Secrets Manager unavailable for "${name}" (${err.name ?? err.code}). ` +
          `Falling back to .env.test — this is only acceptable in non-production!`
        );
        value = localEnv[name];
      } else {
        throw err;
      }
    }
  }

  cache.set(name, value);
  return value;
}

/**
 * Pre-warm the cache by resolving every registered secret at startup.
 * Call this once during application boot so that all secrets are cached
 * before the first request arrives.
 *
 * @returns {Promise<Map<string, string>>} Resolved name→value map.
 */
async function loadAllSecrets() {
  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      const value = await getSecret(name);
      return { name, value };
    })
  );

  const failed = [];
  for (const result of results) {
    if (result.status === 'rejected') {
      failed.push(result.reason);
    }
  }

  if (failed.length > 0) {
    throw new AggregateError(failed, `[secrets] Failed to load ${failed.length} secret(s) at startup`);
  }

  return new Map(cache);
}

module.exports = { getSecret, loadAllSecrets, REQUIRED_SECRET_NAMES };

'use strict';

/**
 * app.js
 *
 * All runtime secrets are resolved through secrets.js, which fetches from
 * AWS Secrets Manager (with a local .env.test fallback for development).
 * No secret value is ever imported or hard-coded directly in this file.
 */

const express = require('express');
const { getSecret, loadAllSecrets } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * Example: a route that consumes a secret on-demand.
 * getSecret() is cached after the first call, so there is no extra
 * network round-trip on subsequent requests.
 */
app.get('/db-status', async (req, res, next) => {
  try {
    const dbUrl = await getSecret('DATABASE_URL');
    // Use only the non-sensitive parts of the URL in the response
    const { hostname, port, pathname } = new URL(dbUrl);
    res.json({ connected: true, host: hostname, port, database: pathname.replace('/', '') });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// Error handler
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('[app] Unhandled error:', err.message);
  res.status(500).json({ error: 'Internal server error' });
});

// ---------------------------------------------------------------------------
// Startup — pre-warm all secrets before accepting traffic
// ---------------------------------------------------------------------------

async function start() {
  try {
    console.log('[app] Loading secrets…');
    await loadAllSecrets();
    console.log('[app] All secrets loaded successfully.');
  } catch (err) {
    console.error('[app] Startup failed — could not load required secrets:', err.message);
    process.exit(1);
  }

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

start();

module.exports = app;

