/**
 * secrets.js
 *
 * Centralised secret resolution with a two-tier strategy:
 *
 *   1. PRIMARY  – AWS Secrets Manager (used in every environment where
 *                 the env-var `USE_AWS_SECRETS_MANAGER` is set to "true").
 *   2. FALLBACK – .env.test loaded via dotenv (local / CI development only,
 *                 never used when USE_AWS_SECRETS_MANAGER=true).
 *
 * The module reads the *names* (keys) of required secrets from .env.test at
 * startup so that the set of expected secrets is always derived from that
 * single source of truth.  The *values* stored in .env.test are only ever
 * used as the local fallback; they are never logged, exported, or embedded
 * in any form.
 *
 * Usage
 * -----
 *   const { getSecret, loadAllSecrets } = require('./secrets');
 *
 *   // Fetch a single secret by its name (key from .env.test):
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Pre-fetch every required secret and receive them as a plain object
 *   // whose keys are the secret names and values are the resolved strings:
 *   const secrets = await loadAllSecrets();
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover the canonical list of required secret names.
//    We intentionally use our own minimal parser here instead of calling
//    dotenv.config() at the top level, which would immediately populate
//    process.env with the local values.  Keeping parsing separate means we
//    can choose *when* (and *whether*) to fall back to those values.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * parseDotEnvKeys(filePath)
 *
 * Returns an array of the variable *names* declared in a .env file.
 * Lines that are blank or start with `#` are ignored.
 * Values are intentionally discarded — this function only extracts keys.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {string[]}      - Ordered array of unique secret names.
 */
function parseDotEnvKeys(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`[secrets] Required env file not found: ${filePath}`);
  }

  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  const keys  = [];

  for (const raw of lines) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;          // skip comments / blanks

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;                         // malformed line – skip

    const key = line.slice(0, eqIndex).trim();
    if (key && !keys.includes(key)) {
      keys.push(key);
    }
  }

  return keys;
}

/** Immutable list of every secret name declared in .env.test. */
const REQUIRED_SECRET_NAMES = Object.freeze(parseDotEnvKeys(ENV_FILE));

// ---------------------------------------------------------------------------
// 2. Lazy-load dotenv only when the local fallback path is actually needed.
//    This avoids polluting process.env in production where Secrets Manager
//    is the authoritative source.
// ---------------------------------------------------------------------------

let _dotenvLoaded = false;

/**
 * ensureDotenvLoaded()
 *
 * Calls dotenv.config() exactly once, pointing at .env.test.
 * Subsequent calls are no-ops.
 */
function ensureDotenvLoaded() {
  if (_dotenvLoaded) return;

  // dotenv is a devDependency; fail clearly if it is somehow absent.
  let dotenv;
  try {
    dotenv = require('dotenv');
  } catch {
    throw new Error(
      '[secrets] The "dotenv" package is required for local fallback but is not installed. ' +
      'Run: npm install dotenv'
    );
  }

  const result = dotenv.config({ path: ENV_FILE });
  if (result.error) {
    throw new Error(`[secrets] dotenv failed to load ${ENV_FILE}: ${result.error.message}`);
  }

  _dotenvLoaded = true;
}

// ---------------------------------------------------------------------------
// 3. AWS Secrets Manager client — instantiated lazily so that the module can
//    be imported in local/CI environments without triggering AWS SDK calls.
// ---------------------------------------------------------------------------

let _smClient = null;

/**
 * getSecretsManagerClient()
 *
 * Returns a cached SecretsManagerClient.  The client is constructed with
 * no hard-coded credentials; it relies entirely on the standard AWS
 * credential-provider chain (IAM role, environment variables, ~/.aws, etc.).
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSecretsManagerClient() {
  if (_smClient) return _smClient;

  let SecretsManagerClient;
  try {
    ({ SecretsManagerClient } = require('@aws-sdk/client-secrets-manager'));
  } catch {
    throw new Error(
      '[secrets] The "@aws-sdk/client-secrets-manager" package is required when ' +
      'USE_AWS_SECRETS_MANAGER=true but is not installed. ' +
      'Run: npm install @aws-sdk/client-secrets-manager'
    );
  }

  _smClient = new SecretsManagerClient({
    region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    // No credentials or endpoint hard-coded here.
    // Credentials are resolved by the SDK's default provider chain:
    //   IAM role → ECS task role → env vars → ~/.aws/credentials
  });

  return _smClient;
}

// ---------------------------------------------------------------------------
// 4. In-process cache so each secret is only fetched from Secrets Manager
//    once per process lifetime.  This avoids redundant API calls and reduces
//    latency for frequently-accessed secrets.
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const _cache = new Map();

// ---------------------------------------------------------------------------
// 5. Core resolution logic
// ---------------------------------------------------------------------------

/**
 * resolveFromSecretsManager(name)
 *
 * Fetches a single secret string from AWS Secrets Manager.
 * The secret is expected to be stored either as a plain-text string value
 * or as a JSON object where `name` is one of the top-level keys.
 *
 * Caching: resolved values are stored in `_cache` so subsequent calls for
 * the same name are synchronously available without another network round-trip.
 *
 * @param {string} name - The secret name / ARN as stored in Secrets Manager.
 * @returns {Promise<string>}
 * @throws  If the secret does not exist or the SDK call fails.
 */
async function resolveFromSecretsManager(name) {
  if (_cache.has(name)) return _cache.get(name);

  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client  = getSecretsManagerClient();
  const command = new GetSecretValueCommand({ SecretId: name });

  let response;
  try {
    response = await client.send(command);
  } catch (err) {
    throw new Error(
      `[secrets] Failed to fetch secret "${name}" from AWS Secrets Manager: ${err.message}`
    );
  }

  // Secrets Manager can return either SecretString or SecretBinary.
  if (!response.SecretString) {
    throw new Error(
      `[secrets] Secret "${name}" was returned as binary; only string secrets are supported.`
    );
  }

  // If the secret value is a JSON object, attempt to extract the key that
  // matches `name`.  This supports the common pattern of bundling multiple
  // related secrets under one Secrets Manager entry.
  let value;
  try {
    const parsed = JSON.parse(response.SecretString);
    if (typeof parsed === 'object' && parsed !== null && name in parsed) {
      value = String(parsed[name]);
    } else {
      // JSON but no matching key — use the raw string as-is.
      value = response.SecretString;
    }
  } catch {
    // Not JSON — treat the whole thing as a plain string value.
    value = response.SecretString;
  }

  _cache.set(name, value);
  return value;
}

/**
 * resolveFromLocalEnv(name)
 *
 * Loads .env.test (once) and returns the value of `name` from process.env.
 *
 * @param {string} name
 * @returns {string}
 * @throws  If the key is not present after loading .env.test.
 */
function resolveFromLocalEnv(name) {
  ensureDotenvLoaded();

  const value = process.env[name];
  if (value === undefined) {
    throw new Error(
      `[secrets] Secret "${name}" not found in ${ENV_FILE}. ` +
      'Add it to .env.test or verify the key name.'
    );
  }

  return value;
}

// ---------------------------------------------------------------------------
// 6. Public API
// ---------------------------------------------------------------------------

/**
 * useSecretsManager()
 *
 * Returns true when the runtime is configured to use AWS Secrets Manager.
 * Set USE_AWS_SECRETS_MANAGER=true in the environment to enable it.
 *
 * @returns {boolean}
 */
function useSecretsManager() {
  return process.env.USE_AWS_SECRETS_MANAGER === 'true';
}

/**
 * getSecret(name)
 *
 * Resolves a single secret by name using the active strategy:
 *
 *   - USE_AWS_SECRETS_MANAGER=true  → AWS Secrets Manager (with in-process cache)
 *   - otherwise                     → local .env.test fallback (development only)
 *
 * @param {string} name - Must be one of the names declared in .env.test.
 * @returns {Promise<string>} The resolved secret value.
 * @throws  {Error} If `name` is not in the required list, or resolution fails.
 *
 * @example
 *   const dbUrl = await getSecret('DATABASE_URL');
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    throw new Error(
      `[secrets] Unknown secret name: "${name}". ` +
      `Declared secrets are: ${REQUIRED_SECRET_NAMES.join(', ')}`
    );
  }

  if (useSecretsManager()) {
    return resolveFromSecretsManager(name);
  }

  // Local fallback — load from .env.test via dotenv.
  return resolveFromLocalEnv(name);
}

/**
 * loadAllSecrets()
 *
 * Resolves every secret declared in .env.test in parallel and returns a
 * plain object mapping each name to its resolved value.
 *
 * Useful at application startup to eagerly validate that all required secrets
 * are accessible before the server begins accepting traffic.
 *
 * @returns {Promise<Record<string, string>>}
 *
 * @example
 *   const secrets = await loadAllSecrets();
 *   // secrets.DATABASE_URL, secrets.STRIPE_SECRET_KEY, ...
 */
async function loadAllSecrets() {
  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => [name, await getSecret(name)])
  );
  return Object.fromEntries(entries);
}

/**
 * getRequiredSecretNames()
 *
 * Returns a copy of the list of secret names parsed from .env.test.
 * Useful for introspection and testing — no values are exposed.
 *
 * @returns {string[]}
 */
function getRequiredSecretNames() {
  return [...REQUIRED_SECRET_NAMES];
}

module.exports = {
  getSecret,
  loadAllSecrets,
  getRequiredSecretNames,
};

// app.js
//
// Express application.  All secrets are resolved through secrets.js, which
// either fetches them from AWS Secrets Manager (when USE_AWS_SECRETS_MANAGER=true)
// or falls back to .env.test via dotenv for local development.
//
// No secret values are hard-coded, logged, or imported directly here.

'use strict';

const express = require('express');
const { getSecret, loadAllSecrets } = require('./secrets');

const app = express();

// ---------------------------------------------------------------------------
// Startup: eagerly validate that every required secret is reachable before
// the server begins accepting traffic.  The resolved values are held in a
// local `secrets` object scoped to this module; they are never attached to
// `process.env` or any globally visible object.
// ---------------------------------------------------------------------------

let secrets = {};   // populated during startServer(); empty until then

/**
 * startServer()
 *
 * Resolves all secrets, then starts the HTTP listener.
 * Call this once at process startup — see the bottom of this file.
 *
 * @returns {Promise<import('http').Server>}
 */
async function startServer() {
  // Resolve all declared secrets up-front.  If any secret is missing or
  // inaccessible the promise rejects and the process exits before binding
  // to a port, which gives a clear startup-time failure rather than a
  // confusing runtime error later.
  secrets = await loadAllSecrets();

  // Example: use individual secrets where they are actually needed.
  // Route handlers that need a secret call getSecret(name) lazily, or read
  // from the `secrets` map populated here.  Either pattern is fine — both
  // avoid ever touching process.env for secret values.

  // ------------------------------------------------------------------
  // Routes
  // ------------------------------------------------------------------

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  // Example route that demonstrates fetching a single secret on demand.
  // In a real app you would use the value (e.g. to sign a request), not
  // expose it — this just shows the call pattern.
  app.get('/db-ping', async (req, res) => {
    try {
      // Fetch lazily (already cached after loadAllSecrets() above).
      const dbUrl = await getSecret('DATABASE_URL');

      // NEVER return the raw secret value to the client.
      // Use it internally — here we only confirm it was resolved.
      const host = new URL(dbUrl).host;   // e.g. "db.internal:5432"
      res.json({ status: 'ok', dbHost: host });
    } catch (err) {
      res.status(500).json({ status: 'error', message: err.message });
    }
  });

  // ------------------------------------------------------------------
  // Start listening
  // ------------------------------------------------------------------

  return new Promise((resolve) => {
    const server = app.listen(3000, () => {
      console.log('Server running on port 3000');
      resolve(server);
    });
  });
}

// ---------------------------------------------------------------------------
// Module entry-point: only start automatically when this file is run directly
// (node app.js), not when it is require()'d by tests.
// ---------------------------------------------------------------------------

if (require.main === module) {
  startServer().catch((err) => {
    console.error('[app] Failed to start:', err.message);
    process.exit(1);
  });
}

module.exports = { app, startServer };

