let passed = 0;
let failed = 0;

async function test(description, fn) {
  try {
    await fn();
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`     ${err.message}`);
    failed++;
  }
}

function assert(condition, message) {
  if (!condition) throw new Error(message || 'Assertion failed');
}

function assertEqual(actual, expected, label) {
  if (actual !== expected) {
    throw new Error(`${label || 'assertEqual'}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

// ---------------------------------------------------------------------------
// Helpers to reset module state between tests
// ---------------------------------------------------------------------------

/**
 * freshSecrets(overrides)
 *
 * Re-requires secrets.js with a clean module registry so each test starts
 * with a blank cache and no lingering dotenv or SDK state.
 *
 * `overrides` is a plain object of require-path → mock-module mappings that
 * are injected into the module's require() calls via Module._resolveFilename
 * monkey-patching.  This keeps the implementation code unmodified while
 * letting tests substitute the AWS SDK and dotenv.
 */
function freshSecrets({ useAws = false, sdkResponse = null, sdkError = null } = {}) {
  // Clear the cached module so a fresh copy is evaluated each time.
  Object.keys(require.cache).forEach((key) => {
    if (key.includes('secrets.js') && !key.includes('secrets.test')) {
      delete require.cache[key];
    }
  });

  // Control the USE_AWS_SECRETS_MANAGER flag.
  process.env.USE_AWS_SECRETS_MANAGER = useAws ? 'true' : 'false';

  if (useAws) {
    // Stub @aws-sdk/client-secrets-manager.
    const fakeClient = {
      send: async () => {
        if (sdkError) throw sdkError;
        return sdkResponse;
      },
    };

    // Inject the stub via require.cache before loading secrets.js.
    const sdkPath = require.resolve('@aws-sdk/client-secrets-manager');
    require.cache[sdkPath] = {
      id: sdkPath,
      filename: sdkPath,
      loaded: true,
      exports: {
        SecretsManagerClient: class { send(...args) { return fakeClient.send(...args); } },
        GetSecretValueCommand: class { constructor(input) { this.input = input; } },
      },
    };
  }

  return require('./secrets');
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

console.log('\nsecrets.js — unit tests\n');

// ── 1. Key-name parsing ────────────────────────────────────────────────────

test('getRequiredSecretNames returns only the key names from .env.test', async () => {
  const { getRequiredSecretNames } = freshSecrets();
  const names = getRequiredSecretNames();

  assert(Array.isArray(names), 'should return an array');
  assert(names.length > 0, 'should not be empty');

  // Spot-check that well-known keys from .env.test are present.
  const expected = [
