    'LOGFIRE_TOKEN',
  ];
  for (const key of expected) {
    assert(names.includes(key), `should include "${key}"`);
  }
});

test('getRequiredSecretNames contains no empty strings or duplicates', async () => {
  const { getRequiredSecretNames } = freshSecrets();
  const names = getRequiredSecretNames();
  const unique = new Set(names);

  assertEqual(unique.size, names.length, 'no duplicates');
  assert(names.every((n) => n.length > 0), 'no empty strings');
});

test('getRequiredSecretNames returns a copy — mutations do not affect the module', async () => {
  const { getRequiredSecretNames } = freshSecrets();
  const a = getRequiredSecretNames();
  a.push('INJECTED_KEY');
  const b = getRequiredSecretNames();
  assert(!b.includes('INJECTED_KEY'), 'internal list should be immutable from outside');
});

// ── 2. Unknown secret guard ────────────────────────────────────────────────

test('getSecret rejects with a clear error for an unknown secret name', async () => {
  const { getSecret } = freshSecrets();
  let threw = false;
  try {
    await getSecret('TOTALLY_UNKNOWN_KEY_XYZ');
  } catch (err) {
