  const sdkPath = require.resolve('@aws-sdk/client-secrets-manager');

  Object.keys(require.cache).forEach((key) => {
    if (key.includes('secrets.js') && !key.includes('secrets.test')) {
      delete require.cache[key];
    }
  });
