          return Promise.resolve({ SecretString: 'cached-value' });
        }
      },
      GetSecretValueCommand: class { constructor(i) { this.input = i; } },
    },
  };

  const { getSecret } = require('./secrets');

  await getSecret('DATABASE_URL');
  await getSecret('DATABASE_URL');   // second call — must NOT hit the SDK again
  await getSecret('DATABASE_URL');   // third call — same

  assertEqual(callCount, 1, 'SDK should be called exactly once per name');
});

