 * - Tests validate key-name parsing, routing logic, caching, error paths, and
 *   the local fallback — they never assert on actual secret values from .env.test.
 *
 * Run with:  node secrets.test.js
 */

'use strict';

const path   = require('path');
const Module = require('module');

// ---------------------------------------------------------------------------
// Minimal test harness (no external dependencies)
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;
const results = [];   // collect so we can print after all async tests settle

async function test(description, fn) {
  try {
    await fn();
    results.push({ ok: true, description });
    passed++;
  } catch (err) {
    results.push({ ok: false, description, error: err.message });
    failed++;
  }
}

function assert(condition, message) {
  if (!condition) throw new Error(message || 'Assertion failed');
}

function assertEqual(actual, expected, label) {
  if (actual !== expected) {
    throw new Error(
      `${label || 'assertEqual'}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`
    );
  }
