// ---------------------------------------------------------------------------
// Stub helpers
//
// Because @aws-sdk/client-secrets-manager and dotenv may not be installed,
// we inject fake modules directly into require.cache using synthetic paths.
// secrets.js uses lazy require() calls, so as long as the cache entry exists
// under the exact string that require() will resolve to, Node returns the stub.
//
// For packages that are NOT installed we register the stub under the canonical
// Node resolution path that secrets.js would compute:
//   node_modules/@aws-sdk/client-secrets-manager
//   node_modules/dotenv
// We synthesise those paths ourselves so require.resolve() never has to
// succeed for the real package.
// ---------------------------------------------------------------------------

const ROOT          = path.resolve(__dirname);
const SECRETS_PATH  = path.join(ROOT, 'secrets.js');
const SDK_FAKE_PATH = path.join(ROOT, 'node_modules', '@aws-sdk', 'client-secrets-manager', 'index.js');
const DOTENV_FAKE_PATH = path.join(ROOT, 'node_modules', 'dotenv', 'lib', 'main.js');

/**
 * Override Module._resolveFilename so that when secrets.js calls
 * require('@aws-sdk/client-secrets-manager') or require('dotenv'), Node
 * returns our synthetic paths instead of throwing "Cannot find module".
 */
const _origResolve = Module._resolveFilename.bind(Module);
Module._resolveFilename = function (request, parent, isMain, options) {
  if (request === '@aws-sdk/client-secrets-manager') return SDK_FAKE_PATH;
  if (request === 'dotenv')                          return DOTENV_FAKE_PATH;
  return _origResolve(request, parent, isMain, options);
};

// ---------------------------------------------------------------------------
// freshSecrets({ useAws, sdkSend, dotenvValues })
//
// Re-requires secrets.js with a clean cache and the requested stubs in place.
//
//   useAws       – set USE_AWS_SECRETS_MANAGER=true
//   sdkSend      – async function used as SecretsManagerClient.prototype.send
//   dotenvValues – plain object returned as process.env overrides by dotenv stub
// ---------------------------------------------------------------------------

function freshSecrets({ useAws = false, sdkSend = null, dotenvValues = null } = {}) {
  // Reset module cache for secrets.js only.
  delete require.cache[SECRETS_PATH];

  process.env.USE_AWS_SECRETS_MANAGER = useAws ? 'true' : 'false';

  // ── AWS SDK stub ─────────────────────────────────────────────────────────
  if (useAws && sdkSend) {
    require.cache[SDK_FAKE_PATH] = {
      id: SDK_FAKE_PATH,
      filename: SDK_FAKE_PATH,
      loaded: true,
      exports: {
        SecretsManagerClient: class {
          send(...args) { return sdkSend(...args); }
        },
        GetSecretValueCommand: class {
          constructor(input) { this.input = input; }
        },
      },
    };
  } else {
    delete require.cache[SDK_FAKE_PATH];
  }

  // ── dotenv stub ──────────────────────────────────────────────────────────
  // Provide a stub that injects `dotenvValues` into process.env instead of
  // reading from disk.  If dotenvValues is null we let it read the real file
  // (the values are already present in .env.test on disk).
  if (dotenvValues !== null) {
    require.cache[DOTENV_FAKE_PATH] = {
      id: DOTENV_FAKE_PATH,
      filename: DOTENV_FAKE_PATH,
      loaded: true,
      exports: {
        config({ path: p } = {}) {
          Object.assign(process.env, dotenvValues);
          return { parsed: dotenvValues };
        },
      },
    };
  } else {
    // Use real dotenv behaviour: stub that simply reads .env.test for real.
    // We install a pass-through that calls the *real* dotenv if available,
    // or replicates its minimal behaviour inline so the test is self-contained.
    require.cache[DOTENV_FAKE_PATH] = {
      id: DOTENV_FAKE_PATH,
      filename: DOTENV_FAKE_PATH,
      loaded: true,
      exports: {
        config({ path: envPath } = {}) {
