/**
 * secrets.js
 *
 * Centralised secret resolution with a two-tier strategy:
 *
 *   1. PRIMARY  – AWS Secrets Manager (used in every environment where
 *                 the env-var `USE_AWS_SECRETS_MANAGER` is set to "true").
 *   2. FALLBACK – .env.test loaded via dotenv (local / CI development only,
 *                 never used when USE_AWS_SECRETS_MANAGER=true).
 *
 * The module reads the *names* (keys) of required secrets from .env.test at
 * startup so that the set of expected secrets is always derived from that
 * single source of truth.  The *values* stored in .env.test are only ever
 * used as the local fallback; they are never logged, exported, or embedded
 * in any form.
 *
 * Usage
 * -----
 *   const { getSecret, loadAllSecrets } = require('./secrets');
 *
 *   // Fetch a single secret by its name (key from .env.test):
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Pre-fetch every required secret and receive them as a plain object
 *   // whose keys are the secret names and values are the resolved strings:
 *   const secrets = await loadAllSecrets();
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover the canonical list of required secret names.
//    We intentionally use our own minimal parser here instead of calling
//    dotenv.config() at the top level, which would immediately populate
//    process.env with the local values.  Keeping parsing separate means we
//    can choose *when* (and *whether*) to fall back to those values.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * parseDotEnvKeys(filePath)
 *
 * Returns an array of the variable *names* declared in a .env file.
 * Lines that are blank or start with `#` are ignored.
 * Values are intentionally discarded — this function only extracts keys.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {string[]}      - Ordered array of unique secret names.
 */
function parseDotEnvKeys(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`[secrets] Required env file not found: ${filePath}`);
  }

  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  const keys  = [];

  for (const raw of lines) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;          // skip comments / blanks

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;                         // malformed line – skip

    const key = line.slice(0, eqIndex).trim();
    if (key && !keys.includes(key)) {
      keys.push(key);
    }
  }

  return keys;
}

/** Immutable list of every secret name declared in .env.test. */
const REQUIRED_SECRET_NAMES = Object.freeze(parseDotEnvKeys(ENV_FILE));

// ---------------------------------------------------------------------------
// 2. Lazy-load dotenv only when the local fallback path is actually needed.
//    This avoids polluting process.env in production where Secrets Manager
//    is the authoritative source.
// ---------------------------------------------------------------------------

let _dotenvLoaded = false;

/**
 * ensureDotenvLoaded()
