{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with AWS Secrets Manager integration",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js",
    "test": "NODE_ENV=test node app.js"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

/**
 * secrets.js
 *
 * Centralised secret resolution with two-tier strategy:
 *
 *   1. PRIMARY  — AWS Secrets Manager (used in staging / production)
 *   2. FALLBACK — .env.test loaded via dotenv (used in local development /
 *                 CI when NODE_ENV !== 'production')
 *
 * The module never stores secret values in module-level variables that
 * persist across calls; each getSecret() call either hits Secrets Manager
 * or reads from the process environment that dotenv populated at startup.
 *
 * Required secret names are derived exclusively from the keys present in
 * .env.test — no names are hard-coded in this file.
 */

'use strict';

const path = require('path');
const fs   = require('fs');

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// 1. Determine runtime environment
// ---------------------------------------------------------------------------

const IS_PRODUCTION = process.env.NODE_ENV === 'production';
const ENV_FILE      = path.resolve(__dirname, '.env.test');

// ---------------------------------------------------------------------------
// 2. Discover required secret names from .env.test
//    Parses only the *keys* — values are never read or used by this module.
//    The resulting array is the authoritative list of secrets the app needs.
// ---------------------------------------------------------------------------

/**
 * Parse the key names from a dotenv-formatted file without evaluating or
 * storing the values.  Lines that are blank or start with '#' are ignored.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {string[]}       Ordered list of variable names found in the file.
 */
function parseSecretNamesFromEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(
      `Secret name registry not found: ${filePath}\n` +
      'Create a .env.test file whose keys list the required secrets.'
    );
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  return lines.reduce((names, line) => {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) return names;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) return names;          // malformed line — skip

    const key = trimmed.slice(0, eqIndex).trim();
    if (key) names.push(key);
    return names;
  }, []);
}

/** Immutable list of secret names the application requires. */
const REQUIRED_SECRET_NAMES = Object.freeze(parseSecretNamesFromEnvFile(ENV_FILE));

// ---------------------------------------------------------------------------
// 3. Fallback: load .env.test into process.env for non-production runtimes
//    dotenv.config() is called once at module load time.  It only sets
//    variables that are not already present in the environment (safe to call
//    even when the real values were injected by the CI/CD system).
// ---------------------------------------------------------------------------

if (!IS_PRODUCTION) {
  // Require dotenv lazily so production bundles that strip dev-dependencies
  // do not fail at startup.
  // eslint-disable-next-line global-require
  const dotenv = require('dotenv');
  dotenv.config({ path: ENV_FILE });
}

// ---------------------------------------------------------------------------
// 4. AWS Secrets Manager client
//    Constructed once and reused; credentials come from the standard AWS
//    credential chain (IAM role, env vars, ~/.aws/credentials, etc.) — never
//    from hard-coded values.
// ---------------------------------------------------------------------------

let _smClient = null;

/**
 * Returns a lazily-initialised SecretsManagerClient.
 * Deferred so that the module can be imported in development without
 * requiring valid AWS credentials to be present at startup.
 *
 * @returns {SecretsManagerClient}
 */
function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
      // Credentials intentionally omitted — resolved by the SDK's default
      // credential provider chain (instance role, env vars, profile, etc.)
    });
  }
  return _smClient;
}

// ---------------------------------------------------------------------------
// 5. In-process cache to avoid redundant Secrets Manager API calls within
//    the same process lifetime.  Keys are secret names; values are the
//    resolved plaintext strings.  The cache is intentionally NOT exported so
//    callers cannot inspect or mutate it.
// ---------------------------------------------------------------------------

const _cache = new Map();

// ---------------------------------------------------------------------------
// 6. Core API
// ---------------------------------------------------------------------------

/**
 * Fetch the value of a named secret.
 *
 * Resolution order:
 *   a) In-process cache (avoids repeat API calls in the same process)
 *   b) AWS Secrets Manager  (always attempted in production; attempted first
 *      in development too, so a real secret overrides the local fallback)
 *   c) process.env          (populated from .env.test by dotenv in non-prod)
 *
 * @param {string} name  The secret name as it appears in .env.test and in
 *                       AWS Secrets Manager.
 * @returns {Promise<string>}  The plaintext secret value.
 * @throws  Will throw if the secret cannot be resolved through any strategy.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`getSecret requires a non-empty string name, got: ${JSON.stringify(name)}`);
  }

  // (a) Cache hit
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  // (b) AWS Secrets Manager
  try {
    const command  = new GetSecretValueCommand({ SecretId: name });
    const response = await getSmClient().send(command);

    // Secrets Manager returns either SecretString or SecretBinary
    const value = response.SecretString ?? Buffer.from(response.SecretBinary, 'base64').toString('utf8');

    _cache.set(name, value);
    return value;
  } catch (smError) {
    if (IS_PRODUCTION) {
      // In production there is no fallback — surface the error immediately.
      throw new Error(
        `[secrets] Failed to fetch "${name}" from Secrets Manager (production): ${smError.message}`
      );
    }

    // (c) Local fallback via process.env (non-production only)
    const envValue = process.env[name];
    if (envValue !== undefined) {
      // Store in cache so subsequent calls in the same process are free
      _cache.set(name, envValue);
      return envValue;
    }

    // Neither source could resolve the secret
    throw new Error(
      `[secrets] Could not resolve "${name}".\n` +
      `  • Secrets Manager error: ${smError.message}\n` +
      `  • No matching key found in process.env / .env.test`
    );
  }
}

/**
 * Fetch all required secrets in parallel and return them as a plain object.
 * Useful for one-shot initialisation at application startup.
 *
 * @returns {Promise<Record<string, string>>}
 *   An object whose keys match REQUIRED_SECRET_NAMES and whose values are
 *   the resolved secret strings.
 */
async function getAllSecrets() {
  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => [name, await getSecret(name)])
  );
  return Object.fromEntries(entries);
}

// ---------------------------------------------------------------------------
// 7. Exports
// ---------------------------------------------------------------------------

module.exports = {
  /** Ordered, frozen list of secret names parsed from .env.test keys. */
  REQUIRED_SECRET_NAMES,
  /** Fetch a single secret by name (Secrets Manager → env fallback). */
  getSecret,
  /** Fetch every required secret in parallel. */
  getAllSecrets,
};

'use strict';

/**
 * app.js
 *
 * Application entry-point.  Secrets are resolved through secrets.js which
 * fetches them from AWS Secrets Manager (with a local .env.test fallback for
 * development).  No secret values are imported directly or hard-coded here.
 */

const express = require('express');
const { getSecret, getAllSecrets, REQUIRED_SECRET_NAMES } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Startup: verify all required secrets are resolvable before accepting traffic
// ---------------------------------------------------------------------------

/**
 * Resolves every required secret at startup so misconfigured environments
 * fail fast — before the server binds to a port — rather than at the first
 * request that happens to need a particular secret.
 *
 * The resolved values are intentionally NOT stored in module-level variables;
 * each part of the application that needs a secret calls getSecret() directly,
 * keeping the secret's lifetime as short as possible.
 */
async function validateSecrets() {
  console.log(`[startup] Validating ${REQUIRED_SECRET_NAMES.length} required secret(s): ${REQUIRED_SECRET_NAMES.join(', ')}`);

  // getAllSecrets() fetches in parallel and populates the in-process cache, so
  // subsequent getSecret() calls in route handlers are effectively synchronous.
  await getAllSecrets();

  console.log('[startup] All secrets resolved successfully.');
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * Example of a route that uses a secret at request time.
 * getSecret() is awaited directly — the resolved value is used only within
 * this request's scope and is never attached to the response or logged.
 */
app.get('/db-status', async (req, res) => {
  try {
    const dbUrl = await getSecret('DATABASE_URL');

    // Use the URL only to derive non-sensitive connection metadata.
    // The secret value itself is never included in the response.
    const { hostname, port, pathname } = new URL(dbUrl);
    res.json({
      status:   'connected',
      host:     hostname,
      port:     port || 5432,
      database: pathname.replace(/^\//, ''),
    });
  } catch (err) {
    console.error('[/db-status] Secret resolution failed:', err.message);
    res.status(503).json({ status: 'unavailable', reason: 'secret resolution failed' });
  }
});

// ---------------------------------------------------------------------------
// Boot sequence
// ---------------------------------------------------------------------------

async function start() {
  try {
    await validateSecrets();

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`[startup] Server running on port ${PORT} (NODE_ENV=${process.env.NODE_ENV || 'development'})`);
    });
  } catch (err) {
    console.error('[startup] Fatal: could not start server.', err.message);
    process.exit(1);
  }
}

// Only call start() when this file is run directly (not when it is
// require()'d by a test runner that manages its own lifecycle).
if (require.main === module) {
  start();
}

module.exports = { app, getSecret };

