/**
 * secrets.js
 *
 * Centralised secret resolution with two-tier strategy:
 *
 *   1. PRODUCTION (NODE_ENV === 'production'):
 *      Every call to getSecret(name) fetches the named secret from AWS Secrets
 *      Manager.  The secret is expected to be stored as a plaintext string
 *      (not a JSON blob), which is the simplest and most common convention for
 *      individual API keys / connection strings.  The caller receives the
 *      resolved value; no secret value is ever written to disk or logged.
 *
 *   2. DEVELOPMENT / TEST (all other NODE_ENV values):
 *      getSecret(name) falls back to the process environment, which is
 *      populated at start-up by loading .env.test via dotenv.  This keeps the
 *      developer loop fast while keeping the production code-path identical.
 *
 * Secret *names* (not values) are derived automatically from .env.test:
 * every key defined in that file becomes a required secret name, so there is
 * no separate list to maintain.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ─── 1. Parse .env.test to discover required secret names ────────────────────
// We parse the file ourselves rather than calling dotenv.config() here so that
// we control exactly when (and whether) values are loaded into process.env.
// Only the *names* (keys) are extracted; values are only loaded in non-prod.

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parse a .env file and return { name -> rawLine } for every non-comment,
 * non-empty KEY=VALUE line.  Returns an empty object if the file is absent.
 *
 * @returns {{ [name: string]: string }}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const entries = {};
  const lines   = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;          // skip blanks / comments

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;                                 // skip malformed lines

    const key = trimmed.slice(0, eqIdx).trim();
    if (key) entries[key] = trimmed.slice(eqIdx + 1).trim();   // store raw value string
  }

  return entries;
}

const envFileEntries = parseEnvFile(ENV_FILE);

/**
 * The set of secret names this application requires, derived entirely from the
 * keys present in .env.test.  No secret names are hardcoded here.
 *
 * @type {Set<string>}
 */
const REQUIRED_SECRET_NAMES = new Set(Object.keys(envFileEntries));

// ─── 2. Load .env.test values into process.env for non-production runs ────────
// In production these values are intentionally NOT loaded; everything comes
// from Secrets Manager.

const IS_PRODUCTION = process.env.NODE_ENV === 'production';

if (!IS_PRODUCTION) {
  // Populate process.env only with keys that are not already set, preserving
  // any real environment variables that the developer may have overridden.
  for (const [key, rawValue] of Object.entries(envFileEntries)) {
    if (!(key in process.env)) {
      // Strip optional surrounding quotes that dotenv-style files sometimes use
      const value = rawValue.replace(/^(['"`])(.*)\1$/, '$2');
      process.env[key] = value;
    }
  }
}

// ─── 3. AWS Secrets Manager client (lazy-initialised) ────────────────────────

/** @type {SecretsManagerClient | null} */
let smClient = null;

/**
 * Return (and lazily create) the Secrets Manager client.
 * Region is read from the environment so nothing is hardcoded.
 *
 * @returns {SecretsManagerClient}
 */
function getSmClient() {
  if (!smClient) {
    smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    });
  }
  return smClient;
}

// ─── 4. Per-name in-process cache to avoid redundant API calls ───────────────

/** @type {Map<string, string>} */
const secretCache = new Map();

// ─── 5. Public API ────────────────────────────────────────────────────────────

/**
 * Fetch the value of a named secret.
 *
 * In production the value is retrieved from AWS Secrets Manager (with an
 * in-process cache so each name is fetched at most once per process lifetime).
 *
 * In development/test the value is read from process.env, which was populated
 * from .env.test above.
 *
 * @param {string} name  - The secret name as it appears in .env.test *and* in
 *                         AWS Secrets Manager.  Must be one of the names
 *                         declared in .env.test.
 * @returns {Promise<string>}
 * @throws {Error} If the name is not in the required set, or if Secrets
 *                 Manager returns no value, or if the local fallback is unset.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.has(name)) {
    throw new Error(
      `Unknown secret "${name}". ` +
      `Allowed names (from .env.test): ${[...REQUIRED_SECRET_NAMES].join(', ')}`
    );
  }

  // ── Production: fetch from AWS Secrets Manager ──────────────────────────
  if (IS_PRODUCTION) {
    if (secretCache.has(name)) {
      return secretCache.get(name);
    }

    const command  = new GetSecretValueCommand({ SecretId: name });
    const response = await getSmClient().send(command);

    // Secrets Manager returns either SecretString (text) or SecretBinary.
    // We only support plaintext secrets here; binary secrets are out of scope.
    const value = response.SecretString;
    if (value === undefined || value === null) {
      throw new Error(
        `Secret "${name}" exists in Secrets Manager but has no SecretString value. ` +
        'Binary secrets are not supported.'
      );
    }

    secretCache.set(name, value);
    return value;
  }

  // ── Development / test: read from process.env (populated from .env.test) ─
  const value = process.env[name];
  if (value === undefined || value === '') {
    throw new Error(
      `Secret "${name}" is not set in process.env. ` +
      'Ensure .env.test contains a value for this key when running outside production.'
    );
  }
  return value;
