 * Pre-warm the cache by fetching every required secret in parallel.
 * Call this once at application start-up in production to surface
 * misconfiguration errors early (fail-fast) rather than at the first
 * request that needs each secret.
 *
 * @returns {Promise<void>}
 */
async function loadAllSecrets() {
  await Promise.all([...REQUIRED_SECRET_NAMES].map(name => getSecret(name)));
}

module.exports = { getSecret, loadAllSecrets, REQUIRED_SECRET_NAMES };

'use strict';

/**
 * app.js
 *
 * Application entry-point.  All secrets are resolved through secrets.js —
 * never read directly from process.env or .env files here.
 *
 * Start-up sequence
 * ─────────────────
 * 1. loadAllSecrets() fetches every required secret at once (fail-fast).
 * 2. The resolved values are passed explicitly to subsystems that need them.
 * 3. The HTTP server only begins accepting connections after secrets are ready.
