  try {
    const dbUrl = await getSecret('DATABASE_URL');

    // In real code you would open (or reuse) a DB connection here.
    // We only expose a safe, derived property — not the URL itself.
    const host = new URL(dbUrl).hostname;
    res.json({ connected: true, host });
  } catch (err) {
    console.error('Failed to retrieve DATABASE_URL:', err.message);
    res.status(500).json({ error: 'Could not connect to database' });
  }
});

// ─── Start-up ────────────────────────────────────────────────────────────────

async function start() {
  // Fetch all secrets up-front so any misconfiguration is caught before the
  // first request arrives rather than mid-flight.
  console.log('Loading secrets…');
  await loadAllSecrets();
  console.log('All secrets loaded successfully.');

  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

start().catch(err => {
  console.error('Fatal: failed to start application:', err.message);
  process.exit(1);
});

module.exports = app;

