{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with AWS Secrets Manager integration",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node --test"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

/**
 * secrets.js
 *
 * Centralised secret resolution with two-tier strategy:
 *
 *   1. PRIMARY  – AWS Secrets Manager (used in all deployed environments).
 *   2. FALLBACK – .env.test loaded via dotenv (used only when
 *                 NODE_ENV=development or NODE_ENV=test, and only when the
 *                 Secrets Manager call fails or is explicitly bypassed).
 *
 * The list of required secret names is derived exclusively from the keys that
 * are present in .env.test, so no secret names (and certainly no secret
 * values) are hardcoded here.
 *
 * Usage:
 *   const { getSecret, requireSecrets } = require('./secrets');
 *
 *   // Fetch a single secret by name:
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Resolve every required secret and return them as a plain object:
 *   const secrets = await requireSecrets();
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

const ENV_FILE        = path.resolve(__dirname, '.env.test');
const IS_LOCAL        = ['development', 'test'].includes(process.env.NODE_ENV);
const AWS_REGION      = process.env.AWS_REGION || 'us-east-1';

// ---------------------------------------------------------------------------
// Step 1 – Derive the required secret names from .env.test keys.
//
// We parse the file ourselves rather than calling dotenv.config() so that we
// never accidentally write the values into process.env.  Only the *names*
// (keys) are used at module load time; the values are only accessed later,
// inside getSecret(), and only as a local fallback.
// ---------------------------------------------------------------------------

/**
 * Parse a dotenv-formatted file and return { key -> value } without touching
 * process.env.  Lines starting with '#' and empty lines are ignored.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {{ [key: string]: string }}
 */
function parseDotEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const parsed = {};
  const lines  = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const raw of lines) {
    const line = raw.trim();

    // Skip comments and blank lines.
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = line.slice(0, eqIdx).trim();
    // Strip optional surrounding quotes from the value.
    const value = line.slice(eqIdx + 1).trim().replace(/^(['"`])(.*)\1$/, '$2');

    if (key) parsed[key] = value;
  }

  return parsed;
}

// The complete map of local fallback values (populated lazily on first use so
// the file is only read when actually needed).
let _localSecrets = null;

function getLocalSecrets() {
  if (_localSecrets === null) {
    _localSecrets = parseDotEnvFile(ENV_FILE);
  }
  return _localSecrets;
}

/**
 * The authoritative list of secret names this application requires.
 * Derived solely from the keys present in .env.test.
 *
 * @type {string[]}
 */
const REQUIRED_SECRET_NAMES = Object.keys(parseDotEnvFile(ENV_FILE));

// ---------------------------------------------------------------------------
// Step 2 – AWS Secrets Manager client (created lazily).
// ---------------------------------------------------------------------------

let _smClient = null;

function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

// ---------------------------------------------------------------------------
// Step 3 – Core resolution logic.
// ---------------------------------------------------------------------------

/**
 * Fetch a single secret value by name.
 *
 * Resolution order:
 *   a) AWS Secrets Manager  — always attempted first.
 *   b) .env.test fallback   — used only when IS_LOCAL is true AND the
 *                             Secrets Manager call throws / returns nothing.
 *
 * The function never falls back silently in production: if both sources fail
 * outside a local environment, it throws so the process fails fast rather
 * than running with missing credentials.
 *
 * @param {string} name  The secret name / key, e.g. 'DATABASE_URL'.
 * @returns {Promise<string>}
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`getSecret: 'name' must be a non-empty string (got ${JSON.stringify(name)})`);
  }

  let smError = null;

  // --- a) Try Secrets Manager first -------------------------------------------
  try {
    const client  = getSmClient();
    const command = new GetSecretValueCommand({ SecretId: name });
    const response = await client.send(command);

    // Secrets Manager returns either SecretString or SecretBinary.
    if (response.SecretString !== undefined && response.SecretString !== null) {
      // The secret may be stored as a raw string or as a JSON object whose
      // top-level key matches the requested name.
      try {
        const parsed = JSON.parse(response.SecretString);
        if (typeof parsed === 'object' && parsed !== null && name in parsed) {
          return String(parsed[name]);
        }
        // If it's a JSON object without the expected key, return it as-is
        // so the caller can decide what to do with structured secrets.
        return response.SecretString;
      } catch {
        // Not JSON — treat as a plain string value.
        return response.SecretString;
      }
    }

    if (response.SecretBinary) {
      // Binary secrets: decode to a UTF-8 string.
      const buf = Buffer.isBuffer(response.SecretBinary)
        ? response.SecretBinary
        : Buffer.from(response.SecretBinary);
      return buf.toString('utf8');
    }

    // Secrets Manager responded but with no usable value.
    smError = new Error(`Secrets Manager returned an empty value for "${name}"`);
  } catch (err) {
    smError = err;
  }

  // --- b) Local fallback (development / test only) ----------------------------
  if (IS_LOCAL) {
    const local = getLocalSecrets();
    if (name in local) {
      console.warn(
        `[secrets] Secrets Manager unavailable for "${name}" — using .env.test fallback. ` +
        `Reason: ${smError && smError.message}`
      );
      return local[name];
    }
  }

  // --- c) Hard failure ---------------------------------------------------------
  const context = smError ? ` (Secrets Manager error: ${smError.message})` : '';
  throw new Error(
    `Secret "${name}" could not be resolved${context}. ` +
    `Ensure the secret exists in AWS Secrets Manager or, for local development, ` +
    `add it to .env.test.`
  );
}

// ---------------------------------------------------------------------------
// Step 4 – Convenience helper to resolve ALL required secrets at once.
// ---------------------------------------------------------------------------

/**
 * Resolve every secret listed in REQUIRED_SECRET_NAMES in parallel and return
 * a plain object mapping each name to its resolved value.
 *
 * Throws as soon as any individual secret cannot be resolved.
 *
 * @returns {Promise<{ [name: string]: string }>}
 */
async function requireSecrets() {
  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => [name, await getSecret(name)])
  );
  return Object.fromEntries(entries);
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  /** Ordered list of secret names read from .env.test keys. */
  REQUIRED_SECRET_NAMES,

  /**
   * Fetch a single secret by name from Secrets Manager, with local fallback.
   * @type {(name: string) => Promise<string>}
   */
  getSecret,

  /**
   * Resolve all required secrets in parallel and return them as a plain object.
   * @type {() => Promise<{ [name: string]: string }>}
   */
  requireSecrets,
