 *  • Production  – fetches each secret from AWS Secrets Manager by name.
 *  • Development – falls back to the local .env.test file when the env var
 *                  USE_LOCAL_SECRETS=true is set (or NODE_ENV=test), so
 *                  developers never need live AWS credentials locally.
 *
 * The list of required secret names is derived *solely from the keys* found
 * in .env.test — no values from that file are ever read or embedded here.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1.  Derive the canonical list of required secret names from .env.test keys.
//     We use dotenv's low-level `parse()` so that we can inspect only the
//     key names without loading values into process.env.
// ---------------------------------------------------------------------------

const dotenv      = require('dotenv');
const ENV_FILE    = path.resolve(__dirname, '.env.test');
const _rawContent = fs.readFileSync(ENV_FILE, 'utf8');
const _parsed     = dotenv.parse(_rawContent);          // { KEY: 'value', … }

/**
 * The list of secret names that this application requires.
 * Derived purely from the *keys* of .env.test — values are never used here.
 *
 * @type {string[]}
 */
const REQUIRED_SECRETS = Object.keys(_parsed);

// Immediately discard the parsed object so values don't linger in this scope.
Object.keys(_parsed).forEach(k => delete _parsed[k]);

// ---------------------------------------------------------------------------
// 2.  AWS Secrets Manager client (lazy-initialised to avoid paying the cost
//     in development mode).
// ---------------------------------------------------------------------------

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

/** @type {SecretsManagerClient | null} */
let _smClient = null;

function _getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      // Region is read from the standard AWS_REGION / AWS_DEFAULT_REGION env
      // vars, or from ~/.aws/config — never hard-coded here.
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION,
    });
  }
  return _smClient;
}

// ---------------------------------------------------------------------------
// 3.  Development fallback — load .env.test into process.env *once* when
//     running locally.  We do this lazily so production paths never touch the
//     file at all.
// ---------------------------------------------------------------------------

let _localSecretsLoaded = false;

function _ensureLocalSecrets() {
  if (_localSecretsLoaded) return;
  dotenv.config({ path: ENV_FILE });
  _localSecretsLoaded = true;
}

// ---------------------------------------------------------------------------
// 4.  Core helper: should we use local secrets?
// ---------------------------------------------------------------------------

function _isLocalMode() {
  return (
    process.env.USE_LOCAL_SECRETS === 'true' ||
    process.env.NODE_ENV === 'test' ||
    process.env.NODE_ENV === 'development'
  );
}

// ---------------------------------------------------------------------------
// 5.  In-process cache so we don't hammer Secrets Manager on every call.
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const _cache = new Map();

// ---------------------------------------------------------------------------
// 6.  Public API
// ---------------------------------------------------------------------------

/**
 * Fetches a secret value by name.
 *
 * In production (NODE_ENV=production or USE_LOCAL_SECRETS≠true):
 *   • Calls AWS Secrets Manager's GetSecretValue API.
 *   • Caches the result in-process for the lifetime of the running instance.
 *
 * In development / test (NODE_ENV=test|development or USE_LOCAL_SECRETS=true):
 *   • Loads .env.test via dotenv (once) and reads from process.env.
 *   • This keeps local workflows fast and offline-friendly.
 *
 * @param  {string}          name  - The secret name, matching a key in .env.test
 *                                   and the corresponding secret name stored in
 *                                   AWS Secrets Manager.
 * @returns {Promise<string>}       - Resolves to the plaintext secret value.
 * @throws  {Error}                 - If the secret is not found in either source.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRETS.includes(name)) {
    throw new Error(
      `getSecret: "${name}" is not a recognised secret name. ` +
      `Known secrets: ${REQUIRED_SECRETS.join(', ')}`
    );
  }

  // ── Development / test path ──────────────────────────────────────────────
  if (_isLocalMode()) {
    _ensureLocalSecrets();
    const value = process.env[name];
    if (value === undefined || value === '') {
      throw new Error(
        `getSecret (local): "${name}" not found in ${ENV_FILE}. ` +
        'Ensure the key exists in .env.test.'
      );
    }
    return value;
  }

  // ── Production path ──────────────────────────────────────────────────────
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  const client  = _getSmClient();
  const command = new GetSecretValueCommand({ SecretId: name });

  let response;
  try {
    response = await client.send(command);
  } catch (err) {
    throw new Error(
      `getSecret: Failed to retrieve "${name}" from AWS Secrets Manager. ` +
      `Cause: ${err.message}`
    );
  }

  // Secrets Manager returns either SecretString (text/JSON) or
  // SecretBinary (base64-encoded binary).  We surface SecretString; callers
  // that store JSON can JSON.parse() the result themselves.
  const value = response.SecretString ?? response.SecretBinary?.toString('utf8');

  if (value === undefined || value === null) {
    throw new Error(
      `getSecret: "${name}" was found in Secrets Manager but contained no value.`
    );
  }

  _cache.set(name, value);
  return value;
}

/**
 * Pre-warms the secret cache by fetching all required secrets up-front.
 * Call this once during application startup (production only) so that the
 * first real request is never blocked on a Secrets Manager round-trip.
 *
 * @returns {Promise<void>}
 */
async function loadAllSecrets() {
  if (_isLocalMode()) {
    _ensureLocalSecrets();
    return;
  }
  await Promise.all(REQUIRED_SECRETS.map(name => getSecret(name)));
}

module.exports = {
  REQUIRED_SECRETS,  // Exported for introspection / tests — an array of names.
  getSecret,
  loadAllSecrets,
};

