{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with AWS Secrets Manager integration",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node --test"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

'use strict';

/**
 * secrets.js
 *
 * Centralised secret resolution with two-tier lookup:
 *
 *   1. PRIMARY  — AWS Secrets Manager (used whenever NODE_ENV !== 'development'
 *                 OR when AWS credentials are explicitly present in the
 *                 environment, so staging/production always hits real AWS).
 *   2. FALLBACK — Values parsed from .env.test (used in local development
 *                 when Secrets Manager is unreachable / not configured).
 *
 * Secret names are discovered solely by reading the *keys* from .env.test —
 * no secret values are ever hard-coded in this file.
 *
 * Usage
 * ─────
 *   const { getSecret, loadAllSecrets } = require('./secrets');
 *
 *   // Fetch a single secret (async, cached after first call)
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Pre-warm the cache for all known secrets at startup
 *   await loadAllSecrets();
 */

const path = require('path');
const fs   = require('fs');

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE        = path.resolve(__dirname, '.env.test');
const AWS_REGION      = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

/**
 * We treat the environment as "development-local" when BOTH conditions hold:
 *   • NODE_ENV is 'development' (or not set)
 *   • No real AWS credentials are present in the process environment
 *
 * This means a developer who has AWS credentials configured locally will
 * still hit Secrets Manager — intentional, so they can test the real path.
 */
const hasAwsCredentials = () =>
  !!(process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) ||
  !!(process.env.AWS_PROFILE) ||
  !!(process.env.AWS_CONTAINER_CREDENTIALS_RELATIVE_URI) || // ECS task role
  !!(process.env.AWS_WEB_IDENTITY_TOKEN_FILE);              // IRSA / EKS

const isLocalDev = () =>
  (process.env.NODE_ENV || 'development') === 'development' && !hasAwsCredentials();

// ─── .env.test parser ─────────────────────────────────────────────────────────

/**
 * Parse a .env file and return a plain object of { KEY: 'value' }.
 * Handles:
 *   • Full-line comments  (# …)
 *   • Inline comments     (VAR=value  # comment)
 *   • Optional surrounding quotes (" or ')
 *   • Blank lines
 *
 * Does NOT call dotenv.config() so it never mutates process.env.
 *
 * @param {string} filePath  Absolute path to the env file.
 * @returns {{ [key: string]: string }}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const raw     = fs.readFileSync(filePath, 'utf8');
  const entries = {};

  for (const rawLine of raw.split('\n')) {
    // Strip trailing CR (Windows line-endings) and leading/trailing whitespace
    const line = rawLine.replace(/\r$/, '').trim();

    // Skip blank lines and full-line comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = line.slice(0, eqIdx).trim();
    // Everything after the first '=', before any inline comment, unquoted
    let   value = line.slice(eqIdx + 1).trim();

    // Strip optional surrounding quotes (both ends must match)
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    } else {
      // Remove inline comment (unquoted value):  VAR=abc  # comment
      const commentIdx = value.indexOf(' #');
      if (commentIdx !== -1) {
        value = value.slice(0, commentIdx).trim();
      }
    }

    if (key) entries[key] = value;
  }

  return entries;
}

// ─── Derived constants (computed once at module load) ─────────────────────────

/**
 * The full set of secrets this application needs, derived exclusively from
 * the *keys* present in .env.test.  Values from that file are kept only as
 * a local-dev fallback; they never propagate into production code paths.
 */
const LOCAL_FALLBACK = parseEnvFile(ENV_FILE);

/** Ordered list of secret names the application requires. */
const REQUIRED_SECRET_NAMES = Object.freeze(Object.keys(LOCAL_FALLBACK));

if (REQUIRED_SECRET_NAMES.length === 0) {
  console.warn(
    `[secrets] Warning: no secret names found in ${ENV_FILE}. ` +
    'Ensure the file exists and contains KEY=value lines.'
  );
}

// ─── AWS Secrets Manager client (lazy-initialised) ───────────────────────────

let _smClient = null;

function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

// ─── In-process cache ─────────────────────────────────────────────────────────

/** @type {Map<string, string>} */
const _cache = new Map();

// ─── Core fetch logic ─────────────────────────────────────────────────────────

/**
 * Fetch a single secret value from AWS Secrets Manager.
 * Throws if the secret does not exist or the call fails.
 *
 * @param {string} name  The secret name (or ARN) in Secrets Manager.
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(name) {
  const client  = getSmClient();
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);

  // Secrets Manager returns either SecretString or SecretBinary
  if (response.SecretString !== undefined) {
    return response.SecretString;
  }

  // Binary secret: decode from Buffer/Uint8Array
  const buf = Buffer.isBuffer(response.SecretBinary)
    ? response.SecretBinary
    : Buffer.from(response.SecretBinary);
  return buf.toString('utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Retrieve a secret value by name.
 *
 * Resolution order:
 *   1. In-process cache (populated on first successful fetch).
 *   2. AWS Secrets Manager  — always attempted when not in local-dev mode;
 *      also attempted in local-dev mode when hasAwsCredentials() is true.
 *   3. Local .env.test fallback — only in local-dev mode, and only when
 *      the Secrets Manager call fails or credentials are absent.
 *
 * @param {string} name  The secret name, matching a key in .env.test.
 * @returns {Promise<string>}
 * @throws  {Error} If the secret cannot be resolved from any source.
 */
async function getSecret(name) {
  // 1. Cache hit
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  const localDev = isLocalDev();

  // 2. Attempt Secrets Manager when we are NOT in pure local-dev mode
  if (!localDev) {
    const value = await fetchFromSecretsManager(name);
    _cache.set(name, value);
    return value;
  }

  // 3. Local-dev: try Secrets Manager first (if credentials happen to be
  //    present at call time), then fall back to .env.test
  try {
    const value = await fetchFromSecretsManager(name);
    _cache.set(name, value);
    return value;
  } catch (err) {
    const fallback = LOCAL_FALLBACK[name];
    if (fallback !== undefined) {
      console.warn(
        `[secrets] Secrets Manager unavailable (${err.message}). ` +
        `Using .env.test fallback for "${name}".`
      );
      _cache.set(name, fallback);
      return fallback;
    }
    throw new Error(
      `[secrets] Secret "${name}" not found in Secrets Manager or .env.test fallback.`
    );
  }
}

/**
 * Pre-warm the cache by fetching every secret listed in .env.test.
 * Call this once during application startup to surface missing secrets early
 * rather than discovering them at runtime.
 *
 * @returns {Promise<{ [name: string]: string }>}  Resolved map of all secrets.
 * @throws  {Error} (AggregateError-style message) if any secret fails to load.
 */
async function loadAllSecrets() {
  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      const value = await getSecret(name);
      return { name, value };
    })
  );

  const errors  = [];
  const resolved = {};

  for (const result of results) {
    if (result.status === 'fulfilled') {
      resolved[result.value.name] = result.value.value;
    } else {
      errors.push(result.reason?.message ?? String(result.reason));
    }
  }

  if (errors.length > 0) {
    throw new Error(
      `[secrets] Failed to load ${errors.length} secret(s):\n` +
      errors.map((e) => `  • ${e}`).join('\n')
    );
  }

  return resolved;
}

/**
 * The ordered list of secret names this application expects, derived from
 * the keys present in .env.test.  Useful for validation / auditing.
 *
 * @type {ReadonlyArray<string>}
 */
const requiredSecretNames = REQUIRED_SECRET_NAMES;

module.exports = { getSecret, loadAllSecrets, requiredSecretNames };

'use strict';

/**
 * app.js
 *
 * Application entry point.  All secret values are resolved through
 * secrets.js — never accessed from process.env or hard-coded here.
 */

const express = require('express');
const { loadAllSecrets, getSecret } = require('./secrets');

const app = express();

// ─── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/**
 * Example: a route that consumes a secret at request time.
 *
 * getSecret() is cached after the first call, so there is no per-request
 * round-trip to Secrets Manager.
 */
app.get('/db-check', async (req, res) => {
  try {
    // Only the DATABASE_URL is accessed here — no other secrets are exposed
    const dbUrl = await getSecret('DATABASE_URL');

    // Use only non-sensitive metadata for the response (never echo secret values)
    const urlObj = new URL(dbUrl);
    res.json({
      status: 'ok',
      database: {
        host:     urlObj.hostname,
        port:     urlObj.port || 5432,
        database: urlObj.pathname.replace(/^\//, ''),
        // username and password intentionally omitted
      },
    });
  } catch (err) {
    console.error('[app] Failed to retrieve DATABASE_URL:', err.message);
    res.status(503).json({ status: 'error', message: 'Database configuration unavailable.' });
  }
});

// ─── Startup ──────────────────────────────────────────────────────────────────

async function start() {
  // Pre-warm: fetch all required secrets before accepting traffic.
  // This surfaces missing/misconfigured secrets at boot time rather than
  // mid-request, and amortises Secrets Manager latency.
  console.log('[app] Loading secrets...');
  await loadAllSecrets();
  console.log('[app] All secrets loaded successfully.');

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

start().catch((err) => {
  console.error('[app] Startup failed:', err.message);
  process.exit(1);
});

module.exports = app;

