 * secrets.test.js
 *
 * Node built-in test runner (node --test), no extra test framework needed.
 *
 * Run with:
 *   node --test secrets.test.js
 */

const { test } = require('node:test');
const assert   = require('node:assert/strict');
const path     = require('path');
const Module   = require('module');

// ─── SDK stub factory ─────────────────────────────────────────────────────────
// Builds a minimal @aws-sdk/client-secrets-manager shim that we inject into
// the require cache before loading secrets.js.  This avoids any network calls
// and removes the dependency on the package being installed.

function makeAwsSdkStub({ rejectWith } = {}) {
  return {
    SecretsManagerClient: class MockSecretsManagerClient {
      send(_cmd) {
        if (rejectWith) return Promise.reject(rejectWith);
        // Default: return the SecretId as the value so callers get something
        return Promise.resolve({
          SecretString: `mock-value-for-${_cmd.input?.SecretId ?? 'unknown'}`,
        });
      }
    },
    GetSecretValueCommand: class MockGetSecretValueCommand {
      constructor(input) { this.input = input; }
    },
  };
}

const SDK_MODULE_ID = '@aws-sdk/client-secrets-manager';

/**
 * Load a fresh, isolated copy of secrets.js with a given AWS SDK stub and
 * NODE_ENV value.  Each call produces an independent module instance so tests
 * do not interfere with each other.
 */
function loadSecretsModule(nodeEnv, sdkStub) {
  // Inject the stub before resolving secrets.js
  const stubCacheEntry = {
    id: SDK_MODULE_ID,
    filename: SDK_MODULE_ID,
    loaded: true,
    exports: sdkStub,
  };
  require.cache[SDK_MODULE_ID] = stubCacheEntry;

  // Patch _resolveFilename so the stub key is returned verbatim (not resolved
  // to a real file path, which would not exist without npm install)
  const origResolve = Module._resolveFilename;
  Module._resolveFilename = function (request, ...args) {
    if (request === SDK_MODULE_ID) return SDK_MODULE_ID;
    return origResolve.call(this, request, ...args);
  };

  // Save and override NODE_ENV
  const savedNodeEnv = process.env.NODE_ENV;
  process.env.NODE_ENV = nodeEnv;

  // Delete any previously cached copy of secrets.js
  const secretsPath = require.resolve('./secrets');
  delete require.cache[secretsPath];

  let mod;
  try {
    mod = require('./secrets');
  } finally {
    // Restore everything regardless of whether require() threw
    process.env.NODE_ENV = savedNodeEnv;
    Module._resolveFilename = origResolve;
    delete require.cache[SDK_MODULE_ID];
  }

  return mod;
}

// ─── Tests ────────────────────────────────────────────────────────────────────

test('requiredSecretNames is derived from .env.test keys — no hard-coded values', () => {
  const noOpStub = makeAwsSdkStub(); // won't be called in this sync test
  const { requiredSecretNames } = loadSecretsModule('development', noOpStub);

  // Keys we expect based on the current .env.test
  const expected = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
  ];

  assert.deepEqual(requiredSecretNames, expected,
    'requiredSecretNames should exactly match .env.test keys in file order');
});

test('getSecret — local dev, SM unavailable → falls back to .env.test', async () => {
  const failingStub = makeAwsSdkStub({
    rejectWith: new Error('Network error (simulated)'),
  });
  const { getSecret } = loadSecretsModule('development', failingStub);

  // Should NOT throw; should resolve via .env.test
  const value = await getSecret('DATABASE_URL');
  assert.ok(value.startsWith('postgres://'),
    'Fallback DATABASE_URL should start with postgres://');
  // Ensure we got a real-looking value from the file, not an empty string
  assert.ok(value.length > 10, 'Fallback value should be non-trivial');
});

