  const successStub = makeAwsSdkStub(); // returns mock-value-for-<name>
  const { getSecret } = loadSecretsModule('development', successStub);

  const value = await getSecret('STRIPE_SECRET_KEY');
  assert.equal(value, 'mock-value-for-STRIPE_SECRET_KEY',
    'Should use Secrets Manager value when SM call succeeds');
});

test('getSecret — production, SM available → uses SM value', async () => {
  const successStub = makeAwsSdkStub();
  const { getSecret } = loadSecretsModule('production', successStub);

  const value = await getSecret('ANTHROPIC_API_KEY');
  assert.equal(value, 'mock-value-for-ANTHROPIC_API_KEY',
    'Production path should return SM value');
});

test('getSecret — production, SM unavailable → throws, never uses fallback', async () => {
  const failingStub = makeAwsSdkStub({
    rejectWith: new Error('AccessDeniedException'),
  });
  const { getSecret } = loadSecretsModule('production', failingStub);

  await assert.rejects(
    () => getSecret('DATABASE_URL'),
    /AccessDeniedException/,
    'Production should propagate the SM error, not silently fall back'
  );
});

test('getSecret — unknown secret in local dev → throws informative error', async () => {
  const failingStub = makeAwsSdkStub({
    rejectWith: new Error('ResourceNotFoundException'),
  });
  const { getSecret } = loadSecretsModule('development', failingStub);

  await assert.rejects(
    () => getSecret('TOTALLY_UNKNOWN_KEY'),
    /TOTALLY_UNKNOWN_KEY/,
    'Error message should name the missing secret'
  );
});

test('getSecret — result is cached; SM is called exactly once', async () => {
  let callCount = 0;
  const countingStub = {
    SecretsManagerClient: class {
      send(cmd) {
        callCount++;
        return Promise.resolve({ SecretString: `val-${cmd.input.SecretId}` });
      }
    },
    GetSecretValueCommand: class {
      constructor(input) { this.input = input; }
    },
  };

  const { getSecret } = loadSecretsModule('production', countingStub);

  const v1 = await getSecret('LOGFIRE_TOKEN');
  const v2 = await getSecret('LOGFIRE_TOKEN');
  const v3 = await getSecret('LOGFIRE_TOKEN');

  assert.equal(callCount, 1, 'Secrets Manager should be called only once per secret');
  assert.equal(v1, v2);
  assert.equal(v2, v3);
});

