  // SM fails for some secrets, no local-dev fallback (production mode)
  const failingStub = makeAwsSdkStub({
    rejectWith: new Error('Simulated SM outage'),
  });
  const { loadAllSecrets } = loadSecretsModule('production', failingStub);

  await assert.rejects(
