{
  "name": "secrets-manager-app",
  "version": "1.0.0",
  "description": "Express app using AWS Secrets Manager with local .env.test fallback",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js",
    "test": "NODE_ENV=test node app.js"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

/**
 * secrets.js
 *
 * Provides a getSecret(name) function that resolves secret values from
 * AWS Secrets Manager in production, with a local .env.test fallback for
 * development/test environments.
 *
 * Design decisions
 * ────────────────
 * 1. Secret *names* are discovered by parsing the keys out of .env.test so
 *    that the required-secrets list never has to be hardcoded here.
 * 2. Secret *values* are NEVER logged, stored in module-level variables that
 *    could be serialised, or embedded in source.  They are returned directly
 *    to the caller so the caller controls their lifetime.
 * 3. The fallback path uses dotenv to load the file at runtime; this module
 *    itself never reads or handles the raw values — it just asks process.env
 *    for them after dotenv has populated it.
 * 4. AWS credentials for Secrets Manager must be supplied via the standard
 *    AWS credential chain (env vars, ~/.aws/credentials, IAM role, etc.).
 *    They are NOT read from .env.test.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE      = path.resolve(__dirname, '.env.test');
const IS_PRODUCTION = process.env.NODE_ENV === 'production';
const AWS_REGION    = process.env.AWS_REGION || 'us-east-1';

// ─── Parse required secret names from .env.test ───────────────────────────────
// We read only the KEY portion of each non-comment, non-blank line so that
// secret values never pass through this module at load time.

function parseSecretNames(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    return [];
  }

  const lines = fs.readFileSync(envFilePath, 'utf8').split('\n');
  const names = [];

  for (const line of lines) {
    const trimmed = line.trim();
    // Skip blank lines and comment lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    // Take only the key name — everything left of the first '='
    const key = trimmed.slice(0, eqIndex).trim();
    if (key) names.push(key);
  }

  return names;
}

/**
 * The list of secret names this application requires.
 * Derived purely from the keys in .env.test; no values are read here.
 */
const REQUIRED_SECRET_NAMES = parseSecretNames(ENV_FILE);

// ─── Local fallback: load .env.test via dotenv ────────────────────────────────
// dotenv populates process.env; the raw values stay inside Node's process
// memory and are never touched by this module directly.

function loadLocalEnv() {
  try {
    // Require lazily so production bundles can omit dotenv if desired
    const dotenv = require('dotenv');
    const result = dotenv.config({ path: ENV_FILE });
    if (result.error) {
      throw result.error;
    }
  } catch (err) {
    throw new Error(`[secrets] Failed to load local env file "${ENV_FILE}": ${err.message}`);
  }
}

// Load the local file once at module initialisation if not in production.
// This mirrors the previous dotenv.config() call so existing code keeps working.
if (!IS_PRODUCTION) {
  loadLocalEnv();
}

// ─── AWS Secrets Manager client ───────────────────────────────────────────────
// Created lazily — only instantiated when actually needed in production —
// so the module can be required in all environments without SDK overhead.

let _smClient = null;
function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

// ─── In-process cache ─────────────────────────────────────────────────────────
// Caches resolved secrets for the lifetime of the process to avoid redundant
// API calls.  The cache holds the value strings in memory (just as process.env
// would) — if you need stricter isolation, clear it between requests or set
// SECRETS_DISABLE_CACHE=true.

const _cache = new Map();
const DISABLE_CACHE = process.env.SECRETS_DISABLE_CACHE === 'true';

// ─── Core function ────────────────────────────────────────────────────────────

/**
 * Retrieve a secret value by name.
 *
 * In production  → fetches from AWS Secrets Manager.
 * In development → reads from process.env (populated by dotenv from .env.test).
 *
 * Supports two Secrets Manager value formats:
 *   • Plain string  – returned as-is.
 *   • JSON object   – the key matching `name` is extracted, falling back to
 *                     the full JSON string so callers can parse it themselves.
 *
 * @param  {string} name  The secret name / environment-variable key.
 * @returns {Promise<string>} The resolved secret value.
 * @throws  If the secret cannot be found in either source.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`[secrets] getSecret() requires a non-empty string name, got: ${JSON.stringify(name)}`);
  }

  // ── Local / development path ────────────────────────────────────────────────
  if (!IS_PRODUCTION) {
    const value = process.env[name];
    if (value === undefined) {
      throw new Error(
        `[secrets] Secret "${name}" not found in process.env. ` +
        `Check that it is defined in ${ENV_FILE}.`
      );
    }
    return value;
  }

  // ── Production path: AWS Secrets Manager ───────────────────────────────────

  // Return cached value if available
  if (!DISABLE_CACHE && _cache.has(name)) {
    return _cache.get(name);
  }

  let rawValue;
  try {
    const command  = new GetSecretValueCommand({ SecretId: name });
    const response = await getSmClient().send(command);

    // Secrets Manager returns either SecretString or SecretBinary
    if (response.SecretString !== undefined) {
      rawValue = response.SecretString;
    } else if (response.SecretBinary) {
      // Binary secrets are returned as a Buffer; decode to UTF-8 string
      rawValue = Buffer.from(response.SecretBinary).toString('utf8');
    } else {
      throw new Error('Response contained neither SecretString nor SecretBinary');
    }
  } catch (err) {
    // Enrich the error message without leaking any partial secret data
    throw new Error(
      `[secrets] Failed to fetch secret "${name}" from AWS Secrets Manager ` +
      `(region: ${AWS_REGION}): ${err.message}`
    );
  }

  // If the stored value is a JSON object (common when multiple secrets are
  // bundled under one Secrets Manager entry), try to extract the named key.
  let resolvedValue = rawValue;
  try {
    const parsed = JSON.parse(rawValue);
    if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
      if (Object.prototype.hasOwnProperty.call(parsed, name)) {
        resolvedValue = parsed[name];
      }
      // else: return the full JSON string and let the caller decide
    }
  } catch {
    // Not JSON — use the raw string as-is
  }

  if (!DISABLE_CACHE) {
    _cache.set(name, resolvedValue);
  }

  return resolvedValue;
}

// ─── Bulk helper ──────────────────────────────────────────────────────────────

/**
 * Fetch all required secrets (those whose names were parsed from .env.test)
 * and return them as a plain object.
 *
 * Useful for an application startup check that ensures every expected secret
 * is present before the server starts accepting traffic.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function getAllSecrets() {
  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => [name, await getSecret(name)])
  );
  return Object.fromEntries(entries);
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  /** Names of all secrets required by this application, derived from .env.test */
  REQUIRED_SECRET_NAMES,

  /**
   * Fetch a single secret by name.
   * Uses AWS Secrets Manager in production, process.env fallback elsewhere.
   */
  getSecret,

  /**
   * Fetch every required secret and return them as a { name: value } object.
   * Handy for startup validation.
   */
  getAllSecrets,
};

/**
 * app.js
 *
 * Express application.  Secrets are loaded via secrets.js, which delegates
 * to AWS Secrets Manager in production and to the local .env.test file in
 * development/test environments.
 *
 * No secret values appear in this file.
 */

'use strict';

const express = require('express');
const { getSecret, getAllSecrets, REQUIRED_SECRET_NAMES } = require('./secrets');

const app = express();

// ─── Startup secret validation ────────────────────────────────────────────────
// Fetches all required secrets eagerly at boot time so the process fails fast
