 * secrets.js
 *
 * Provides a getSecret(name) function that resolves secret values from
 * AWS Secrets Manager in production, with a local .env.test fallback for
 * development/test environments.
 *
 * Design decisions
 * ────────────────
 * 1. Secret *names* are discovered by parsing the keys out of .env.test so
 *    that the required-secrets list never has to be hardcoded here.
 * 2. Secret *values* are NEVER logged, stored in module-level variables that
 *    could be serialised, or embedded in source.  They are returned directly
 *    to the caller so the caller controls their lifetime.
 * 3. The fallback path uses dotenv to load the file at runtime; this module
 *    itself never reads or handles the raw values — it just asks process.env
 *    for them after dotenv has populated it.
 * 4. AWS credentials for Secrets Manager must be supplied via the standard
 *    AWS credential chain (env vars, ~/.aws/credentials, IAM role, etc.).
 *    They are NOT read from .env.test.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE      = path.resolve(__dirname, '.env.test');
const IS_PRODUCTION = process.env.NODE_ENV === 'production';
const AWS_REGION    = process.env.AWS_REGION || 'us-east-1';

// ─── Parse required secret names from .env.test ───────────────────────────────
// We read only the KEY portion of each non-comment, non-blank line so that
// secret values never pass through this module at load time.

function parseSecretNames(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    return [];
  }

  const lines = fs.readFileSync(envFilePath, 'utf8').split('\n');
  const names = [];

  for (const line of lines) {
    const trimmed = line.trim();
    // Skip blank lines and comment lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    // Take only the key name — everything left of the first '='
    const key = trimmed.slice(0, eqIndex).trim();
    if (key) names.push(key);
  }

  return names;
}

/**
 * The list of secret names this application requires.
 * Derived purely from the keys in .env.test; no values are read here.
 */
const REQUIRED_SECRET_NAMES = parseSecretNames(ENV_FILE);

// ─── Local fallback: load .env.test via dotenv ────────────────────────────────
// dotenv populates process.env; the raw values stay inside Node's process
// memory and are never touched by this module directly.

function loadLocalEnv() {
  try {
    // Require lazily so production bundles can omit dotenv if desired
    const dotenv = require('dotenv');
    const result = dotenv.config({ path: ENV_FILE });
    if (result.error) {
      throw result.error;
    }
  } catch (err) {
    throw new Error(`[secrets] Failed to load local env file "${ENV_FILE}": ${err.message}`);
  }
}

// Load the local file once at module initialisation if not in production.
// This mirrors the previous dotenv.config() call so existing code keeps working.
if (!IS_PRODUCTION) {
  loadLocalEnv();
}

// ─── AWS Secrets Manager client ───────────────────────────────────────────────
// Created lazily — only instantiated when actually needed in production —
// so the module can be required in all environments without SDK overhead.

let _smClient = null;
function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

