// Caches resolved secrets for the lifetime of the process to avoid redundant
// API calls.  The cache holds the value strings in memory (just as process.env
// would) — if you need stricter isolation, clear it between requests or set
// SECRETS_DISABLE_CACHE=true.

const _cache = new Map();
const DISABLE_CACHE = process.env.SECRETS_DISABLE_CACHE === 'true';

// ─── Core function ────────────────────────────────────────────────────────────

/**
 * Retrieve a secret value by name.
 *
 * In production  → fetches from AWS Secrets Manager.
 * In development → reads from process.env (populated by dotenv from .env.test).
 *
 * Supports two Secrets Manager value formats:
 *   • Plain string  – returned as-is.
 *   • JSON object   – the key matching `name` is extracted, falling back to
 *                     the full JSON string so callers can parse it themselves.
 *
 * @param  {string} name  The secret name / environment-variable key.
 * @returns {Promise<string>} The resolved secret value.
 * @throws  If the secret cannot be found in either source.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`[secrets] getSecret() requires a non-empty string name, got: ${JSON.stringify(name)}`);
  }

