  if (!IS_PRODUCTION) {
    const value = process.env[name];
    if (value === undefined) {
      throw new Error(
        `[secrets] Secret "${name}" not found in process.env. ` +
        `Check that it is defined in ${ENV_FILE}.`
      );
    }
    return value;
  }

  // ── Production path: AWS Secrets Manager ───────────────────────────────────

  // Return cached value if available
  if (!DISABLE_CACHE && _cache.has(name)) {
    return _cache.get(name);
  }

  let rawValue;
  try {
    const command  = new GetSecretValueCommand({ SecretId: name });
    const response = await getSmClient().send(command);

    // Secrets Manager returns either SecretString or SecretBinary
    if (response.SecretString !== undefined) {
      rawValue = response.SecretString;
    } else if (response.SecretBinary) {
      // Binary secrets are returned as a Buffer; decode to UTF-8 string
      rawValue = Buffer.from(response.SecretBinary).toString('utf8');
    } else {
      throw new Error('Response contained neither SecretString nor SecretBinary');
    }
  } catch (err) {
    // Enrich the error message without leaking any partial secret data
    throw new Error(
      `[secrets] Failed to fetch secret "${name}" from AWS Secrets Manager ` +
