}

// ─── Bulk helper ──────────────────────────────────────────────────────────────

/**
 * Fetch all required secrets (those whose names were parsed from .env.test)
 * and return them as a plain object.
 *
 * Useful for an application startup check that ensures every expected secret
 * is present before the server starts accepting traffic.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function getAllSecrets() {
  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => [name, await getSecret(name)])
