  return Object.fromEntries(entries);
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  /** Names of all secrets required by this application, derived from .env.test */
  REQUIRED_SECRET_NAMES,

  /**
   * Fetch a single secret by name.
   * Uses AWS Secrets Manager in production, process.env fallback elsewhere.
   */
  getSecret,

  /**
   * Fetch every required secret and return them as a { name: value } object.
   * Handy for startup validation.
   */
  getAllSecrets,
};

