/**
 * secrets.js
 *
 * Centralised secret-access layer.
 *
 * Strategy
 * ────────────────────────────────────────────────────────────────────────────
 * Production  (NODE_ENV !== 'development')
 *   Every call to getSecret(name) fetches the secret value from AWS Secrets
 *   Manager.  Successful responses are cached in-process for the lifetime of
 *   the server so that repeated reads do not incur extra API latency or cost.
 *
 * Development (NODE_ENV === 'development')
 *   AWS Secrets Manager is tried first.  If the call fails for any reason
 *   (missing credentials, no network, secret does not exist yet, etc.) the
 *   module transparently falls back to the value that dotenv loaded from
 *   .env.test.  This lets engineers work locally without provisioning real
 *   AWS resources.
 *
 * Secret names
 * ────────────────────────────────────────────────────────────────────────────
 * The canonical list of secret names is derived at start-up by reading the
 * keys that exist in .env.test.  That file is the single source of truth for
 * *which* secrets the application needs; it never acts as a source of real
 * values in production.
 *
 * No secret value is ever hardcoded in this file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── 1. Parse .env.test to discover required secret names ────────────────────
//
// We parse the file manually so that we can extract only the *keys* without
// letting any of the values leak into process.env in production.  dotenv is
// still used in development to populate the fallback environment.

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns the list of secret-name strings declared in .env.test.
 * Lines that are blank or start with # are ignored.
 *
 * @returns {string[]}
 */
function loadRequiredSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] ${ENV_FILE} not found – no required secret names loaded.`);
    return [];
  }

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');
  const names = [];

  for (const raw of lines) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;          // skip blanks / comments

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;                           // malformed line

    const key = line.slice(0, eqIdx).trim();
    if (key) names.push(key);
  }

  return names;
}

/** Immutable list of secret names the application requires. */
const REQUIRED_SECRET_NAMES = Object.freeze(loadRequiredSecretNames());

// ── 2. Development fallback – load .env.test values into process.env ─────────
//
// dotenv.config() is intentionally called only in development so that the
// plaintext .env.test values are never injected into a production process.

const IS_DEV = process.env.NODE_ENV === 'development';

if (IS_DEV) {
  const dotenv = require('dotenv');
  const result = dotenv.config({ path: ENV_FILE });
  if (result.error) {
    console.warn(`[secrets] dotenv could not load ${ENV_FILE}:`, result.error.message);
  } else {
    console.log('[secrets] Development mode: loaded .env.test as fallback values.');
  }
}

// ── 3. AWS Secrets Manager client (lazy-initialised) ─────────────────────────
//
// The client is created once, on first use, so that modules which merely
// import secrets.js do not pay the initialisation cost until a secret is
// actually requested.

let _smClient = null;

function getSecretsManagerClient() {
  if (!_smClient) {
    // Require here (not at the top) to keep the module loadable even when the
    // AWS SDK is not installed (e.g. running tests with a minimal dependency
    // install).
    const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

    _smClient = new SecretsManagerClient({
      // Region is read from the standard AWS_REGION / AWS_DEFAULT_REGION env
      // vars or the shared config file – no hardcoded value here.
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

// ── 4. In-process cache ───────────────────────────────────────────────────────
//
// Maps secret name → resolved string value.  Cache entries are populated on
// first fetch and reused for all subsequent calls within the same process.

const _cache = new Map();

// ── 5. Core fetch logic ───────────────────────────────────────────────────────

/**
 * Fetches a single secret from AWS Secrets Manager.
 *
 * Secrets Manager can store a value either as a plain string or as a
 * JSON-encoded object.  When the stored value is a JSON object this function
 * returns the whole parsed object so callers can destructure individual
 * sub-keys if needed.  When it is a plain string the raw string is returned.
 *
 * @param {string} name  The secret name or ARN as stored in Secrets Manager.
 * @returns {Promise<string|object>}
 */
async function fetchFromSecretsManager(name) {
  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client  = getSecretsManagerClient();
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);

  const raw = response.SecretString ?? Buffer.from(response.SecretBinary, 'base64').toString('utf8');

  // Attempt to parse JSON; return as-is if it is not JSON.
  try {
    return JSON.parse(raw);
  } catch {
    return raw;
  }
}

// ── 6. Public API ─────────────────────────────────────────────────────────────

/**
 * Retrieves the value for a named secret.
 *
 * Resolution order
 * ┌─────────────────────────────────────────────────────────────────┐
 * │ 1. In-process cache                                             │
 * │ 2. AWS Secrets Manager                                          │
 * │ 3. process.env (dev only – populated from .env.test by dotenv)  │
 * └─────────────────────────────────────────────────────────────────┘
 *
 * Throws if the secret cannot be resolved by any means.
 *
 * @param {string} name  Secret name exactly as it appears in .env.test /
 *                       Secrets Manager.
 * @returns {Promise<string|object>}
 */
async function getSecret(name) {
  // ── Cache hit ──────────────────────────────────────────────────────────────
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  // ── AWS Secrets Manager ────────────────────────────────────────────────────
  try {
    const value = await fetchFromSecretsManager(name);
    _cache.set(name, value);
    console.log(`[secrets] Loaded '${name}' from AWS Secrets Manager.`);
    return value;
  } catch (awsError) {
    if (!IS_DEV) {
      // In production there is no fallback – surface the error immediately.
      throw new Error(
        `[secrets] Failed to fetch secret '${name}' from AWS Secrets Manager: ${awsError.message}`
      );
    }

    // ── Development fallback: process.env populated by dotenv ──────────────
    console.warn(
      `[secrets] AWS Secrets Manager unavailable for '${name}' (${awsError.message}). ` +
      `Falling back to .env.test value.`
    );

    const fallback = process.env[name];
    if (fallback === undefined) {
      throw new Error(
        `[secrets] Secret '${name}' not found in AWS Secrets Manager or .env.test. ` +
        `Ensure it is defined in .env.test for local development.`
      );
    }

    _cache.set(name, fallback);
    return fallback;
  }
}

/**
 * Pre-warms the cache by fetching every secret listed in .env.test.
 * Call this once during application start-up to surface missing secrets
 * early rather than at the point of first use.
 *
 * @returns {Promise<Map<string, string|object>>}  A copy of the populated cache.
 */
async function loadAllSecrets() {
  console.log(`[secrets] Pre-loading ${REQUIRED_SECRET_NAMES.length} secret(s):`, REQUIRED_SECRET_NAMES);

  await Promise.all(REQUIRED_SECRET_NAMES.map((name) => getSecret(name)));

  // Return a read-only view of the cache so callers can inspect what was loaded
  // without being able to mutate the internal map.
  return new Map(_cache);
}

module.exports = {
  /** Ordered list of secret names derived from .env.test keys. */
  REQUIRED_SECRET_NAMES,

  /**
   * Fetch a secret by name.  Tries Secrets Manager first; falls back to
   * .env.test in development.  Results are cached in-process.
   */
  getSecret,

  /**
   * Pre-warm the cache for all required secrets at start-up.
   * Recommended: call and await this before app.listen().
   */
  loadAllSecrets,
};

