'use strict';

/**
 * secrets.js — Centralised secret resolution module.
 *
 * Strategy
 * --------
 * 1. Parse .env.test with dotenv to discover the *names* of required secrets.
 *    The values found there are only ever used as a local-development fallback;
 *    they are never forwarded to AWS or logged.
 * 2. In production (NODE_ENV === 'production') every secret is fetched from
 *    AWS Secrets Manager.  The Secrets Manager secret is expected to be stored
 *    as a JSON object whose keys match the variable names in .env.test
 *    (e.g. { "DATABASE_URL": "…", "STRIPE_SECRET_KEY": "…", … }).
 *    The name of that Secrets Manager secret is read from the environment
 *    variable AWS_SECRET_NAME (required in production).
 * 3. In all other environments (development / test) getSecret() falls back to
 *    the value dotenv parsed from .env.test, so local development needs no AWS
 *    credentials.
 *
 * Usage
 * -----
 *   const { getSecret, REQUIRED_SECRET_NAMES } = require('./secrets');
 *
 *   // Returns a promise that resolves to the secret string value.
 *   const dbUrl = await getSecret('DATABASE_URL');
 */

const path = require('path');
const fs   = require('fs');

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover required secret names.
//    dotenv.parse() reads the file content and returns a plain object without
//    mutating process.env, so no secret value ever leaks into the environment
//    via this module.
// ---------------------------------------------------------------------------
const ENV_FILE_PATH = path.resolve(__dirname, '.env.test');

if (!fs.existsSync(ENV_FILE_PATH)) {
  throw new Error(`secrets.js: cannot find required env file at ${ENV_FILE_PATH}`);
}

const _parsedEnv = dotenv.parse(fs.readFileSync(ENV_FILE_PATH));

/**
 * The ordered list of secret names declared in .env.test.
 * Consumers can use this to validate that all required secrets are resolvable
 * at startup rather than discovering missing secrets at request time.
 *
 * @type {string[]}
 */
const REQUIRED_SECRET_NAMES = Object.keys(_parsedEnv);

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client (lazily initialised — only used in production).
// ---------------------------------------------------------------------------

/** @type {SecretsManagerClient | null} */
let _smClient = null;

/** @type {Record<string, string> | null}  In-process cache of the fetched bundle. */
let _secretsCache = null;

/**
 * Return (and lazily create) the SecretsManagerClient.
 * Region is resolved from AWS_REGION / AWS_DEFAULT_REGION env vars, which the
 * AWS SDK honours automatically.  Credentials follow the standard SDK chain
 * (env vars → ~/.aws/credentials → IAM role), so nothing is hardcoded here.
 *
 * @returns {SecretsManagerClient}
 */
function _getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({});
  }
  return _smClient;
}

/**
 * Fetch the full secrets bundle from AWS Secrets Manager and cache it for the
 * lifetime of the process.  The bundle must be stored as a JSON string whose
 * keys are the same variable names listed in .env.test.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function _fetchSecretsBundle() {
  if (_secretsCache) {
    return _secretsCache;
  }

  const secretName = process.env.AWS_SECRET_NAME;
  if (!secretName) {
    throw new Error(
      'secrets.js: AWS_SECRET_NAME environment variable is required in production ' +
      'and must contain the name/ARN of the Secrets Manager secret.'
    );
  }

  const client  = _getSmClient();
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);

  const raw = response.SecretString;
  if (!raw) {
    throw new Error(
      `secrets.js: Secrets Manager returned an empty or binary SecretString for "${secretName}". ` +
      'Only JSON string secrets are supported.'
    );
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(
      `secrets.js: Failed to JSON-parse the SecretString for "${secretName}": ${err.message}`
    );
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new Error(
      `secrets.js: The secret "${secretName}" must be a JSON object mapping secret names to values.`
    );
  }

  // Warn (but do not throw) about declared secrets that are absent in the bundle
  // so misconfiguration surfaces clearly in logs without crashing healthy keys.
  for (const name of REQUIRED_SECRET_NAMES) {
    if (!(name in parsed)) {
      console.warn(`secrets.js: WARNING — secret "${name}" is declared in .env.test but missing from Secrets Manager bundle "${secretName}".`);
    }
  }

  _secretsCache = parsed;
  return _secretsCache;
}

// ---------------------------------------------------------------------------
// 3. Public API
// ---------------------------------------------------------------------------

/**
 * Retrieve the value of a named secret.
 *
 * - In **production** (`NODE_ENV === 'production'`): fetches from AWS Secrets
 *   Manager (result is cached for the process lifetime).
 * - In all other environments: returns the value from .env.test as a
 *   development convenience.  No network call is made.
 *
 * @param {string} name  The secret name, e.g. 'DATABASE_URL'.
 * @returns {Promise<string>}
 * @throws  If the secret cannot be found in either source.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    console.warn(
      `secrets.js: "${name}" is not listed in .env.test. ` +
      'Add it there (with a canary/placeholder value) to register it as a known secret.'
    );
  }

  if (process.env.NODE_ENV === 'production') {
    const bundle = await _fetchSecretsBundle();

    if (!(name in bundle)) {
      throw new Error(
        `secrets.js: Secret "${name}" not found in Secrets Manager bundle. ` +
        'Ensure the secret exists and AWS_SECRET_NAME points to the correct secret.'
      );
    }

    return bundle[name];
  }

  // ---- non-production: fall back to .env.test values ---------------------
  if (!(name in _parsedEnv)) {
    throw new Error(
      `secrets.js: Secret "${name}" not found in .env.test (development fallback).`
    );
  }

  return _parsedEnv[name];
