 * Pre-warm: fetch and cache the entire secrets bundle up front so that the
 * first request is not slowed by a Secrets Manager round-trip.
 * Safe to call in non-production (becomes a no-op).
 *
 * @returns {Promise<void>}
 */
async function loadSecrets() {
  if (process.env.NODE_ENV === 'production') {
    await _fetchSecretsBundle();
