 * The list of secret names this application requires, derived solely from
 * the keys present in .env.test.  Exported so app.js (or tests) can
 * validate that every required secret is resolvable at startup.
 *
 * @type {string[]}
 */
const requiredSecretNames = Object.keys(_localSecrets);

// ---------------------------------------------------------------------------
// 2.  AWS Secrets Manager client
// ---------------------------------------------------------------------------

// Region is read from the environment; falls back to 'us-east-1'.
// Credentials come from the standard AWS credential chain
// (env vars → ~/.aws/credentials → EC2/ECS instance metadata).
// Nothing is hard-coded here.
const _smClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
});

// In-process cache so repeated calls don't hit the API unnecessarily.
// Keys are secret names; values are the resolved secret strings.
const _cache = new Map();

