const fs   = require('fs');
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test to discover the NAMES of required secrets.
//     dotenv.config() is intentionally NOT called here – we never want the
//     raw values to land in process.env automatically; callers must go
//     through getSecret() so the fetch path is always explicit.
// ---------------------------------------------------------------------------
const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns a plain object whose keys are the variable names found in
 * .env.test and whose values are the corresponding local fallback values.
 * Lines starting with '#' and empty lines are ignored.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const raw = fs.readFileSync(filePath, 'utf8');
  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = trimmed.slice(0, eqIdx).trim();
    const value = trimmed.slice(eqIdx + 1).trim();
    if (key) result[key] = value;
  }

  return result;
}

// The set of secret names the application needs, derived solely from the
// keys in .env.test.  Values are kept for the local fallback only.
const localSecrets = parseEnvFile(ENV_FILE);

