/**
 * secrets.js
 *
 * Centralised secret-resolution module.
 *
 * Resolution order (first hit wins):
 *   1. AWS Secrets Manager  – when AWS_REGION is set and NODE_ENV !== 'test'
 *   2. Process environment   – variables already present in process.env
 *      (in development / CI these come from .env.test loaded by dotenv)
 *
 * The module intentionally never hard-codes secret values.  It only reads
 * the *names* of the required secrets from .env.test so that the same list
 * of keys is the single source of truth for both environments.
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1. Load .env.test into process.env when it exists (dev / test fallback).
//    We call config() before anything else so that environment variables are
//    available as the fallback when Secrets Manager is not reachable.
// ---------------------------------------------------------------------------
const dotenvPath = path.resolve(__dirname, '.env.test');

let dotenvParsed = {}; // the raw key→value map from the file

if (fs.existsSync(dotenvPath)) {
  // Load into process.env (will not overwrite variables already set by the
  // shell or a parent process, preserving twelve-factor app conventions).
  try {
    const dotenv = require('dotenv');
    const result = dotenv.config({ path: dotenvPath, override: false });
    if (result.error) {
      console.warn('[secrets] dotenv failed to parse .env.test:', result.error.message);
    } else {
      dotenvParsed = result.parsed ?? {};
    }
  } catch (err) {
    // dotenv is a dev dependency; if it is not installed we still attempt to
    // read the file manually so that the key list is available.
    console.warn('[secrets] dotenv not available, falling back to manual parse:', err.message);
    dotenvParsed = parseDotenvFile(dotenvPath);
  }
}

/**
 * Minimal .env parser used only when dotenv itself is not installed.
 * Handles blank lines, # comments, and KEY=VALUE lines.
 * Does NOT handle multi-line values or shell quoting – sufficient for the
 * simple key=value format used in .env.test.
 *
 * @param {string} filePath
 * @returns {Record<string, string>}
 */
function parseDotenvFile(filePath) {
  const result = {};
  try {
    const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
    for (const raw of lines) {
      const line = raw.trim();
      if (!line || line.startsWith('#')) continue;
      const eqIdx = line.indexOf('=');
      if (eqIdx === -1) continue;
      const key   = line.slice(0, eqIdx).trim();
      const value = line.slice(eqIdx + 1).trim().replace(/^["']|["']$/g, '');
      if (key) {
        result[key] = value;
        // Mirror into process.env only when not already set
        if (process.env[key] === undefined) {
          process.env[key] = value;
        }
      }
    }
  } catch (readErr) {
    console.warn('[secrets] Could not read .env.test:', readErr.message);
  }
  return result;
}

// ---------------------------------------------------------------------------
// 2. Derive the authoritative list of required secret names from .env.test.
//    We use the *keys* of that file as the canonical registry – no values are
//    stored here.
// ---------------------------------------------------------------------------

/**
 * Names of all secrets the application requires, derived exclusively from the
 * keys found in .env.test.  Values are never stored in this array.
 *
 * @type {string[]}
 */
const REQUIRED_SECRET_NAMES = Object.keys(dotenvParsed);

// ---------------------------------------------------------------------------
// 3. AWS Secrets Manager client (lazily initialised).
// ---------------------------------------------------------------------------

/** @type {import('@aws-sdk/client-secrets-manager').SecretsManagerClient | null} */
let smClient = null;

/**
 * Returns (and lazily creates) the Secrets Manager client.
 * Throws if the SDK is not installed – callers fall back to process.env.
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSmClient() {
  if (smClient) return smClient;

  // Throws MODULE_NOT_FOUND if the SDK is not installed, which is caught by
  // callers so they can fall back gracefully.
  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

  smClient = new SecretsManagerClient({
    region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    // Credentials are resolved automatically by the SDK via the standard
    // credential provider chain: env vars → ~/.aws/credentials → IAM role.
    // Never pass explicit key/secret here.
  });

  return smClient;
}

// ---------------------------------------------------------------------------
// 4. In-process cache so each secret name is fetched from Secrets Manager
//    at most once per process lifetime.
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const cache = new Map();

// ---------------------------------------------------------------------------
// 5. Core resolution logic.
// ---------------------------------------------------------------------------

/**
 * Returns true when the runtime environment should attempt to resolve secrets
 * from AWS Secrets Manager.
 *
 * Conditions:
 *  - NODE_ENV must NOT be 'test'  (unit tests run fully offline)
 *  - AWS_REGION (or AWS_DEFAULT_REGION) must be set, indicating that an AWS
 *    environment has been configured
 *
 * @returns {boolean}
 */
function shouldUseSecretsManager() {
  const isTestEnv = (process.env.NODE_ENV === 'test');
  const hasRegion = !!(process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION);
  return !isTestEnv && hasRegion;
}

/**
 * Fetch a single secret string value from AWS Secrets Manager.
 *
 * Secrets Manager stores secrets either as a plain string or as a JSON object.
 * When the stored value is a JSON object, this function returns the stringified
 * JSON; callers that need a specific field should pass a name of the form
 * "secretId/fieldName" (see getSecret for that routing logic).
 *
 * @param {string} secretId  The Secrets Manager secret name or ARN.
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(secretId) {
  const {
    GetSecretValueCommand,
  } = require('@aws-sdk/client-secrets-manager');

  const client   = getSmClient();
  const response = await client.send(new GetSecretValueCommand({ SecretId: secretId }));

  if (typeof response.SecretString === 'string') {
    return response.SecretString;
  }

  if (response.SecretBinary) {
    // Binary secrets are returned as a Uint8Array; decode to UTF-8 string.
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`[secrets] Secret "${secretId}" returned no value from Secrets Manager`);
}

// ---------------------------------------------------------------------------
// 6. Public API
// ---------------------------------------------------------------------------

/**
 * Retrieve the value of a named secret.
 *
 * Resolution order:
 *   1. In-process cache (populated on first successful Secrets Manager fetch)
 *   2. AWS Secrets Manager – when shouldUseSecretsManager() is true
 *   3. process.env         – always available as final fallback (populated from
 *                            .env.test in development via dotenv above)
 *
 * The name supports an optional "/fieldName" suffix for JSON-object secrets:
 *
 *   getSecret('myapp/database')            → entire JSON string (or plain value)
 *   getSecret('myapp/database/password')   → value of the "password" key inside
 *                                            the JSON stored at "myapp/database"
 *
 * @param {string} name  Secret name as it appears in Secrets Manager (or in
 *                       .env.test for local development).
 * @returns {Promise<string>}
 * @throws  When the secret cannot be found in any source.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`[secrets] getSecret() requires a non-empty string name, got: ${JSON.stringify(name)}`);
  }

  // --- Cache hit --------------------------------------------------------
  if (cache.has(name)) {
    return cache.get(name);
  }

  // --- AWS Secrets Manager ---------------------------------------------
  if (shouldUseSecretsManager()) {
    try {
      // Support "secretId/jsonField" notation: try the full name first; if
      // that fails with ResourceNotFoundException, split off the last segment
      // as a JSON field key and retry with the shorter id.
      let rawValue;
      let jsonField = null;

      try {
        rawValue = await fetchFromSecretsManager(name);
      } catch (firstErr) {
        if (firstErr.name === 'ResourceNotFoundException') {
          const lastSlash = name.lastIndexOf('/');
          if (lastSlash > 0) {
            const secretId = name.slice(0, lastSlash);
            jsonField      = name.slice(lastSlash + 1);
            rawValue       = await fetchFromSecretsManager(secretId);
          } else {
            throw firstErr;
          }
        } else {
          throw firstErr;
        }
      }

      // If the caller requested a specific JSON field, parse and extract it.
      let resolvedValue = rawValue;
      if (jsonField) {
        try {
          const parsed = JSON.parse(rawValue);
          if (Object.prototype.hasOwnProperty.call(parsed, jsonField)) {
            resolvedValue = String(parsed[jsonField]);
          } else {
            throw new Error(
              `[secrets] JSON secret does not contain field "${jsonField}"`
            );
          }
        } catch (parseErr) {
          if (parseErr.message.startsWith('[secrets]')) throw parseErr;
          throw new Error(
            `[secrets] Could not parse secret "${name}" as JSON: ${parseErr.message}`
          );
        }
      }

      cache.set(name, resolvedValue);
      return resolvedValue;

    } catch (smErr) {
      // Log the failure but do NOT expose error details that might leak ARNs
      // or account numbers into application logs sent to external services.
      console.error(
        `[secrets] Secrets Manager fetch failed for "${name}" – falling back to process.env. ` +
        `Error type: ${smErr.name}`
      );
      // Fall through to process.env fallback below.
    }
  }

  // --- process.env fallback --------------------------------------------
  const envValue = process.env[name];
  if (envValue !== undefined) {
    // Cache to avoid repeated env lookups, but mark as env-sourced so a
    // future reload can re-check Secrets Manager without being blocked by
    // a stale env value.
    cache.set(name, envValue);
    return envValue;
  }

  // --- Not found anywhere ----------------------------------------------
  throw new Error(
    `[secrets] Secret "${name}" could not be resolved from Secrets Manager or process.env. ` +
    `Ensure it is defined in .env.test for local development or in Secrets Manager for deployed environments.`
  );
}

/**
 * Eagerly resolve all required secrets (those listed as keys in .env.test)
 * and return them as a plain object.
 *
 * Useful at application startup to fail fast if any secret is missing, rather
 * than discovering the problem at request time.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function loadAllSecrets() {
  if (REQUIRED_SECRET_NAMES.length === 0) {
    console.warn('[secrets] No secret names found in .env.test – nothing to load.');
    return {};
  }

  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      const value = await getSecret(name);
      return [name, value];
    })
  );

  return Object.fromEntries(entries);
}

/**
 * Invalidate the in-process secret cache.
 *
 * Call this if you need secrets to be re-fetched (e.g. after a rotation
 * event delivered via an SNS notification).
 *
 * @param {string} [name]  If provided, invalidate only this key.
 *                         If omitted, the entire cache is cleared.
 */
function invalidateCache(name) {
  if (name !== undefined) {
    cache.delete(name);
  } else {
    cache.clear();
  }
}

module.exports = {
  getSecret,
  loadAllSecrets,
  invalidateCache,
  REQUIRED_SECRET_NAMES, // exported for introspection / health checks
};

/**
 * app.js
 *
 * Application entry point.  All secret values are resolved through secrets.js
 * which fetches from AWS Secrets Manager in deployed environments and falls
 * back to .env.test for local development.  No secret values are hard-coded
 * or imported directly here.
 */

'use strict';

const express = require('express');
const { loadAllSecrets, getSecret, REQUIRED_SECRET_NAMES } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Startup: resolve all secrets before the server begins accepting requests.
// This ensures the app fails fast if a required secret is missing, rather
// than surfacing the error mid-request.
// ---------------------------------------------------------------------------

/**
 * Initialise the application: load all secrets, wire up routes, then listen.
 * Exported so tests can call init() without binding a port.
 *
 * @returns {Promise<import('http').Server | import('express').Application>}
 */
async function init() {
  // Load (and cache) every secret declared in .env.test.  In production these
  // come from AWS Secrets Manager; locally they come from the .env.test file.
  let secrets;
  try {
    secrets = await loadAllSecrets();
    console.log(
      `[app] Resolved ${Object.keys(secrets).length} secret(s):`,
      Object.keys(secrets).join(', ')
    );
  } catch (err) {
    console.error('[app] Failed to load required secrets at startup:', err.message);
    process.exit(1);
  }

  // -------------------------------------------------------------------------
  // Routes
  // -------------------------------------------------------------------------

  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      // Surface which secrets are *configured* (names only – never values)
      secretsConfigured: REQUIRED_SECRET_NAMES,
    });
  });

  app.get('/users', (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  /**
   * GET /secret-check
   *
   * Development-only diagnostic endpoint.  Returns the *names* of all
   * required secrets and whether each one resolved successfully.  Secret
   * values are never included in the response.
   */
  app.get('/secret-check', async (req, res) => {
    if (process.env.NODE_ENV === 'production') {
      return res.status(404).json({ error: 'Not found' });
    }

    const results = await Promise.all(
      REQUIRED_SECRET_NAMES.map(async (name) => {
        try {
          await getSecret(name);
          return { name, resolved: true };
        } catch {
          return { name, resolved: false };
        }
      })
    );

    res.json({ secrets: results });
  });

  // -------------------------------------------------------------------------
  // Only bind to a port when this file is run directly (not required by tests)
  // -------------------------------------------------------------------------
  if (require.main === module) {
    const PORT = process.env.PORT || 3000;
    return new Promise((resolve) => {
      const server = app.listen(PORT, () => {
        console.log(`[app] Server running on port ${PORT}`);
        resolve(server);
      });
    });
  }

  return app;
}

// Run immediately when executed directly
if (require.main === module) {
  init().catch((err) => {
    console.error('[app] Unhandled startup error:', err);
    process.exit(1);
  });
}

module.exports = { app, init };

/**
 * tests/secrets.test.js
 *
 * Unit tests for secrets.js.
 *
 * All tests run fully offline – AWS Secrets Manager is stubbed/mocked so no
 * real network calls are made.  Uses Node's built-in `node:test` runner.
 *
 * Run with:  node --test tests/secrets.test.js
