'use strict';

const { test, describe, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const path   = require('path');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Re-require secrets.js with a clean module cache so each test group gets a
 * fresh module instance (no shared state from the in-process cache or the
 * lazy SM client).
 *
 * @returns {typeof import('../secrets')}
 */
function freshSecrets() {
  // Remove all copies of our own modules from the cache
  for (const key of Object.keys(require.cache)) {
    if (key.includes('secrets.js') && !key.includes('node_modules')) {
      delete require.cache[key];
    }
  }
  return require('../secrets');
}

/**
 * Save a snapshot of select process.env keys and restore them after the test.
 *
 * @param {string[]} keys
 * @returns {{ restore: () => void }}
 */
function snapshotEnv(keys) {
  const saved = {};
  for (const k of keys) {
    saved[k] = process.env[k];
  }
  return {
    restore() {
      for (const k of keys) {
        if (saved[k] === undefined) delete process.env[k];
        else process.env[k] = saved[k];
      }
    },
  };
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('REQUIRED_SECRET_NAMES', () => {
  test('is an array of strings', () => {
    const { REQUIRED_SECRET_NAMES } = freshSecrets();
    assert.ok(Array.isArray(REQUIRED_SECRET_NAMES));
    for (const name of REQUIRED_SECRET_NAMES) {
      assert.equal(typeof name, 'string');
    }
  });

  test('contains at least one entry (read from .env.test)', () => {
    const { REQUIRED_SECRET_NAMES } = freshSecrets();
    assert.ok(
      REQUIRED_SECRET_NAMES.length > 0,
      'Expected at least one secret key in .env.test'
    );
  });

  test('contains well-known keys from .env.test', () => {
    const { REQUIRED_SECRET_NAMES } = freshSecrets();
    const expected = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN',
    ];
    for (const key of expected) {
      assert.ok(
        REQUIRED_SECRET_NAMES.includes(key),
        `Expected "${key}" to be in REQUIRED_SECRET_NAMES`
      );
    }
  });

  test('does not include blank lines or comment lines', () => {
    const { REQUIRED_SECRET_NAMES } = freshSecrets();
    for (const name of REQUIRED_SECRET_NAMES) {
      assert.ok(name.trim().length > 0, 'Name should not be blank');
      assert.ok(!name.startsWith('#'), 'Name should not start with #');
    }
  });
});

