    const { getSecret } = freshSecrets();
    // DATABASE_URL is defined in .env.test – dotenv populates process.env
    const value = await getSecret('DATABASE_URL');
    assert.equal(typeof value, 'string');
    assert.ok(value.startsWith('postgres://'), `Expected postgres:// prefix, got: ${value}`);
