    if (eqIdx === -1) continue;
    const key   = line.slice(0, eqIdx).trim();
    const value = line.slice(eqIdx + 1).trim();
    if (key) { secretNames.push(key); localMap.set(key, value); }
  }
  return { secretNames, localMap };
}

const { secretNames, localMap } = parseEnvFile(ENV_FILE);
console.log('Parsed secret names:', secretNames);
console.log('localMap has all keys:', [...localMap.keys()].join(', '));
console.log('No value leakage check — localMap.size === secretNames.length:', localMap.size === secretNames.length);
"

