/**
 * secrets.js
 *
 * Centralised secret-access module.
 *
 * Resolution order
 * ─────────────────
 * 1. AWS Secrets Manager  (always attempted when NODE_ENV !== 'development'
 *    OR when USE_AWS_SECRETS=true is explicitly set)
 * 2. Local .env.test fallback  (used in development / when Secrets Manager
 *    is unreachable AND NODE_ENV === 'development')
 *
 * The module reads the *names* of required secrets from .env.test at startup
 * so that no secret values are ever hardcoded here.
 */

'use strict';

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');
const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE       = path.resolve(__dirname, '.env.test');
const AWS_REGION     = process.env.AWS_REGION || 'us-east-1';
const IS_DEVELOPMENT = process.env.NODE_ENV !== 'production';
const USE_AWS        = process.env.USE_AWS_SECRETS === 'true' || !IS_DEVELOPMENT;

// ─── Parse .env.test — keys only, never values ────────────────────────────────

/**
 * Read the env file and return the list of secret *names* (keys) declared in
 * it.  Values from the file are only used as a local fallback and are never
 * logged or exported.
 *
 * @returns {{ secretNames: string[], localMap: Map<string, string> }}
 */
function parseEnvFile(filePath) {
  const secretNames = [];
  const localMap    = new Map();

  if (!fs.existsSync(filePath)) {
    console.warn(`[secrets] Warning: env file not found at ${filePath}`);
    return { secretNames, localMap };
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = line.slice(0, eqIdx).trim();
    const value = line.slice(eqIdx + 1).trim();

    if (key) {
      secretNames.push(key);
      localMap.set(key, value);  // kept in-memory only for dev fallback
    }
  }

  return { secretNames, localMap };
}

const { secretNames, localMap } = parseEnvFile(ENV_FILE);

// Expose the list of required secret names so callers can iterate them
// without touching values.
module.exports.requiredSecretNames = Object.freeze([...secretNames]);

// ─── AWS Secrets Manager client (lazy – created only when needed) ─────────────

let smClient = null;

function getSmClient() {
  if (!smClient) {
    smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return smClient;
}

// ─── In-process cache (TTL-based) ─────────────────────────────────────────────

const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

/**
 * @type {Map<string, { value: string, expiresAt: number }>}
 */
const cache = new Map();

function getCached(name) {
  const entry = cache.get(name);
  if (entry && Date.now() < entry.expiresAt) return entry.value;
  cache.delete(name);
  return null;
}

function setCached(name, value) {
  cache.set(name, { value, expiresAt: Date.now() + CACHE_TTL_MS });
}

// ─── Core fetch from AWS Secrets Manager ──────────────────────────────────────

/**
 * Fetch a single secret from AWS Secrets Manager.
 * Throws if the secret does not exist or the call fails.
 *
 * @param {string} name  — the secret name / ARN
 * @returns {Promise<string>}
 */
async function fetchFromAws(name) {
  const client  = getSmClient();
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);

  // Secrets Manager returns either SecretString or SecretBinary
  if (response.SecretString !== undefined) {
    // If the stored value is a JSON object (e.g. {"value":"…"}), unwrap it
    try {
      const parsed = JSON.parse(response.SecretString);
      // Return the first string value found, or the raw string if it is not JSON
      if (parsed && typeof parsed === 'object') {
        const firstKey = Object.keys(parsed)[0];
        return String(parsed[firstKey]);
      }
    } catch {
      // Not JSON — return the raw string
    }
    return response.SecretString;
  }

  if (response.SecretBinary) {
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`[secrets] Secret "${name}" returned no value from Secrets Manager`);
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Retrieve a secret value by name.
 *
 * In production (or when USE_AWS_SECRETS=true):
 *   - Checks the in-process cache first
 *   - Fetches from AWS Secrets Manager
 *   - Does NOT fall back to the env file (to prevent silent misconfiguration)
 *
 * In development (NODE_ENV !== 'production' and USE_AWS_SECRETS !== 'true'):
 *   - Tries AWS Secrets Manager first (if reachable)
 *   - Falls back to the local .env.test value when AWS is unavailable
 *
 * @param {string} name  — the secret name as declared in .env.test / Secrets Manager
 * @returns {Promise<string>}
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError('[secrets] getSecret() requires a non-empty string name');
  }

  // 1. Cache hit
  const cached = getCached(name);
  if (cached !== null) return cached;

  // 2. AWS Secrets Manager path
  if (USE_AWS) {
    try {
      const value = await fetchFromAws(name);
      setCached(name, value);
      return value;
    } catch (err) {
      if (IS_DEVELOPMENT) {
        // Graceful degradation in development — fall through to local fallback
        console.warn(
          `[secrets] AWS Secrets Manager unavailable for "${name}" ` +
          `(${err.message}). Falling back to .env.test.`
        );
      } else {
        // In production a missing secret is fatal
        throw new Error(
          `[secrets] Failed to retrieve secret "${name}" from AWS Secrets Manager: ${err.message}`
        );
      }
    }
  }

  // 3. Local .env.test fallback (development only)
  if (IS_DEVELOPMENT && localMap.has(name)) {
    const value = localMap.get(name);
    setCached(name, value);
    return value;
  }

  // 4. Not found anywhere
  throw new Error(
    `[secrets] Secret "${name}" not found. ` +
    (IS_DEVELOPMENT
      ? 'Ensure it is defined in .env.test or in AWS Secrets Manager.'
      : 'Ensure it is stored in AWS Secrets Manager.')
  );
}

/**
 * Pre-warm the cache by fetching every secret listed in .env.test at once.
 * Call this during application startup to surface misconfiguration early and
 * to avoid per-request latency on first use.
 *
 * @returns {Promise<void>}
 */
async function loadAllSecrets() {
  if (secretNames.length === 0) {
    console.warn('[secrets] No secret names found in env file — nothing to pre-load.');
    return;
  }

  console.log(`[secrets] Pre-loading ${secretNames.length} secret(s)…`);

  const results = await Promise.allSettled(
    secretNames.map((name) => getSecret(name))
  );

  const failed = [];
  results.forEach((result, i) => {
    if (result.status === 'rejected') {
      failed.push({ name: secretNames[i], reason: result.reason?.message });
    }
  });

  if (failed.length > 0) {
    const summary = failed.map((f) => `  • ${f.name}: ${f.reason}`).join('\n');
    throw new Error(`[secrets] Failed to load ${failed.length} secret(s):\n${summary}`);
  }

  console.log('[secrets] All secrets loaded successfully.');
}

module.exports.getSecret       = getSecret;
module.exports.loadAllSecrets  = loadAllSecrets;

/**
 * app.js
 *
 * Application entry-point.
 * All secrets are resolved through secrets.js — no values are hardcoded here.
 */

'use strict';

const express = require('express');
const { getSecret, loadAllSecrets, requiredSecretNames } = require('./secrets');

const app = express();

// ─── Health check ─────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── Users (example resource) ─────────────────────────────────────────────────

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ─── Example: endpoint that uses a secret at request time ────────────────────
//
// In a real application you would call getSecret() inside service modules
// (e.g. a database connector, an API client) rather than in route handlers.
// This endpoint demonstrates the pattern without exposing any values.

app.get('/secret-status', async (req, res) => {
  try {
    // Demonstrate fetching a secret by name — we only check that it resolves;
    // the value itself is NEVER sent in the response.
    const secretName = requiredSecretNames[0]; // e.g. "DATABASE_URL"
    if (!secretName) {
      return res.status(500).json({ error: 'No secrets configured' });
    }

    await getSecret(secretName);  // throws if unavailable

    res.json({
      status: 'ok',
      message: `Secret "${secretName}" is accessible`,
    });
  } catch (err) {
    console.error('[app] Secret access error:', err.message);
    res.status(500).json({ error: 'Secret unavailable', detail: err.message });
  }
});

// ─── Startup ──────────────────────────────────────────────────────────────────

async function start() {
  // Pre-warm all secrets from Secrets Manager (or .env.test in development).
  // This surfaces misconfiguration at boot time rather than at the first
  // request that needs a particular secret.
  await loadAllSecrets();

  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

start().catch((err) => {
  console.error('[app] Startup failed:', err.message);
  process.exit(1);
});

module.exports = app;
